insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-reset-review', 'Weekly Reset Review', 'worksheet'::resource_kind, 'A short end-of-week look back at what worked, what drained the client, and what to carry forward.', 'Turn a loose week into one or two concrete adjustments.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client fill this in the day before session so you can start from their own words. Pick one thing to keep and one thing to change, no more. Clients often list everything that went wrong, so steer them toward what they did and what helped.', '[{"id": "f0", "type": "textarea", "label": "One moment this week I was glad I handled the way I did"}, {"id": "f1", "type": "textarea", "label": "What took more energy than I expected"}, {"id": "f2", "type": "textarea", "label": "What helped me recover"}, {"id": "f3", "type": "textarea", "label": "One thing I want to keep doing"}, {"id": "f4", "type": "textarea", "label": "One thing I want to change"}, {"id": "f5", "type": "textarea", "label": "The smallest first step for that change"}, {"id": "f6", "type": "textarea", "label": "Who or what could support me with it"}]'::jsonb, array['review', 'routines', 'goal setting']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('energy-drain-and-refill-inventory', 'Energy Drain and Refill Inventory', 'worksheet'::resource_kind, 'Sorts daily activities and people into those that drain and those that restore the client''s energy.', 'Show the client where energy actually goes and what refills it.', array['Adults']::text[], '20 minutes', 'Ask for real examples from the past two weeks rather than general beliefs. Some items will land in both columns, and that is useful to talk about. Look for one drain that can be trimmed and one refill that can be scheduled, and keep the plan small enough to try this week.', '[{"id": "f0", "type": "textarea", "label": "Activities or people that left me drained"}, {"id": "f1", "type": "textarea", "label": "Activities or people that left me refilled"}, {"id": "f2", "type": "textarea", "label": "Something that surprised me about these lists"}, {"id": "f3", "type": "textarea", "label": "A drain I could shorten, share or say no to"}, {"id": "f4", "type": "textarea", "label": "A refill I could add this week"}, {"id": "f5", "type": "textarea", "label": "When exactly I will do it"}, {"id": "f6", "type": "textarea", "label": "What might get in the way"}]'::jsonb, array['energy', 'burnout', 'self-monitoring']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('difficult-conversation-prep-sheet', 'Difficult Conversation Prep Sheet', 'worksheet'::resource_kind, 'Organizes what the client wants to say, hear and agree on before a hard conversation.', 'Replace rehearsing the worst case with a clear plan for the talk.', array['Adults']::text[], '25 minutes', 'Use it a few days before the conversation and role-play the opening lines in session. Clients often prepare what to say but not what they will do if the other person reacts strongly, so spend time on the pause and exit plan. Adapt the wording for work, family or friends.', '[{"id": "f0", "type": "textarea", "label": "Who I need to talk to and what it is about"}, {"id": "f1", "type": "textarea", "label": "What I most want them to understand"}, {"id": "f2", "type": "textarea", "label": "What I want to ask for"}, {"id": "f3", "type": "textarea", "label": "What I think they might say"}, {"id": "f4", "type": "textarea", "label": "My first two sentences"}, {"id": "f5", "type": "textarea", "label": "What I will do if the talk gets heated"}, {"id": "f6", "type": "textarea", "label": "How I will look after myself afterward"}]'::jsonb, array['communication', 'assertiveness', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('change-landing-plan', 'Change Landing Plan', 'worksheet'::resource_kind, 'Maps a big life change into what stays steady, what shifts and what support is needed.', 'Help the client steady themselves through a move, job change or other transition.', array['Adults']::text[], '30 minutes', 'Start with what will stay the same, since clients in transition tend to focus only on loss or uncertainty. Then sort the changes into ones they can shape and ones they can only respond to. Review the support list together and check that each person on it has actually been asked.', '[{"id": "f0", "type": "textarea", "label": "The change that is happening"}, {"id": "f1", "type": "textarea", "label": "What will stay the same"}, {"id": "f2", "type": "textarea", "label": "What is ending or shifting"}, {"id": "f3", "type": "textarea", "label": "Parts of this I can shape"}, {"id": "f4", "type": "textarea", "label": "Parts I can only respond to"}, {"id": "f5", "type": "textarea", "label": "Small routines I will protect"}, {"id": "f6", "type": "textarea", "label": "People I will tell and lean on"}, {"id": "f7", "type": "textarea", "label": "One thing I am looking forward to"}]'::jsonb, array['transitions', 'planning', 'coping skills']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('specific-gratitude-log', 'Specific Gratitude Log', 'worksheet'::resource_kind, 'Builds a habit of noticing one specific good thing each day and what made it possible.', 'Move gratitude from general statements to specific, noticed moments.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Specific beats general here, so prompt for details of the moment instead of a list of big things. Clients who find gratitude forced can start with neutral or small moments. Review the log together and look for patterns in people, places and times of day.', '[{"id": "f0", "type": "textarea", "label": "Today''s good thing in one sentence"}, {"id": "f1", "type": "textarea", "label": "Where I was and who was there"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body or mood"}, {"id": "f3", "type": "textarea", "label": "What made it possible"}, {"id": "f4", "type": "textarea", "label": "Who I could thank or tell"}, {"id": "f5", "type": "textarea", "label": "A pattern I see across the week"}]'::jsonb, array['gratitude', 'habits', 'positive psychology']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('nighttime-settling-checklist', 'Nighttime Settling Checklist', 'worksheet'::resource_kind, 'A step-by-step evening checklist that gives the body and mind cues of present-day safety before sleep.', 'Support steadier nights through a predictable, grounding routine.', array['Adults']::text[], 'One week', 'Build the checklist together in session and keep it short enough to do when tired. Include checking the room, a grounding step and a comforting sensory cue. It aims to stabilize, so never ask for details of what happened. If nights stay hard, talk through next steps and other supports together.', '[{"id": "f0", "type": "textarea", "label": "What I will do to check my room feels safe"}, {"id": "f1", "type": "textarea", "label": "A grounding step I will use in bed"}, {"id": "f2", "type": "textarea", "label": "A comforting sound, scent or texture I will keep close"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself if I wake up"}, {"id": "f4", "type": "textarea", "label": "Someone or something I can reach for if a night is hard"}, {"id": "f5", "type": "textarea", "label": "How the night went and what helped"}]'::jsonb, array['PTSD and trauma', 'sleep', 'grounding']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('circle-of-control-sort', 'Circle of Control Sort', 'worksheet'::resource_kind, 'Sorts worries into what the client can control, influence or only accept.', 'Direct worry energy toward what can be acted on.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for current worries, not hypothetical ones, and sort them together in three rings. Expect the outer ring to be fullest. The point is to pair each outer-ring worry with a way to ride it out, and each inner-ring worry with one action this week.', '[{"id": "f0", "type": "textarea", "label": "Worries on my mind this week"}, {"id": "f1", "type": "textarea", "label": "Ones I can control directly"}, {"id": "f2", "type": "textarea", "label": "Ones I can only influence"}, {"id": "f3", "type": "textarea", "label": "Ones I can do nothing about"}, {"id": "f4", "type": "textarea", "label": "One action I will take on a controllable worry"}, {"id": "f5", "type": "textarea", "label": "How I will let an uncontrollable worry pass"}, {"id": "f6", "type": "textarea", "label": "What I notice after sorting"}]'::jsonb, array['anxiety', 'worry', 'problem solving']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('energy-matched-task-sorter', 'Energy-Matched Task Sorter', 'worksheet'::resource_kind, 'Sorts tasks by how much energy they need so low-mood days still include something doable.', 'Help the client match tasks to energy instead of waiting to feel better.', array['Adults']::text[], '20 minutes', 'Use it when the client says they can do nothing or everything is too big. Sort tasks into low, medium and high energy and plan which go with which kind of day. Celebrate low-energy wins. Keep your own judgment about whether more support is needed alongside it.', '[{"id": "f0", "type": "textarea", "label": "Tasks I need to do"}, {"id": "f1", "type": "textarea", "label": "Tasks that take very little energy"}, {"id": "f2", "type": "textarea", "label": "Tasks that take medium energy"}, {"id": "f3", "type": "textarea", "label": "Tasks that take a lot of energy"}, {"id": "f4", "type": "textarea", "label": "What I will do on a low-energy day"}, {"id": "f5", "type": "textarea", "label": "What I will do on a better day"}, {"id": "f6", "type": "textarea", "label": "How I felt after doing one task"}]'::jsonb, array['depression', 'pacing', 'scheduling']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('free-time-fill-plan', 'Free Time Fill Plan', 'worksheet'::resource_kind, 'Plans how to use the hours when substance use used to happen, with real alternatives.', 'Prepare for empty time and the urges that come with it.', array['Adults']::text[], '25 minutes', 'Ask the client to name the specific times of day or week when substance use most often happened and what filled them. Plan alternatives that are actually available and appealing, not just virtuous. Review what got used and what flopped, and adjust together without judgment.', '[{"id": "f0", "type": "textarea", "label": "Times when I used to use substances"}, {"id": "f1", "type": "textarea", "label": "What I was doing or feeling then"}, {"id": "f2", "type": "textarea", "label": "What I will do in that time now"}, {"id": "f3", "type": "textarea", "label": "Who I can contact at those times"}, {"id": "f4", "type": "textarea", "label": "Something enjoyable I can look forward to"}, {"id": "f5", "type": "textarea", "label": "What I will do if an urge shows up anyway"}, {"id": "f6", "type": "textarea", "label": "What I will change after this week"}]'::jsonb, array['addiction', 'urges', 'routines']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('anger-needs-behind-the-heat', 'Anger Needs Behind the Heat', 'worksheet'::resource_kind, 'Helps the client name the need, hurt or worry beneath an angry reaction.', 'Connect anger to the need underneath so it can be voiced differently.', array['Adults', 'Teens']::text[], '20 minutes', 'Use a recent event the client can still recall without being flooded, and do it after the heat has passed. Ask what was at stake for them. Many clients have few words for hurt or worry, so offer a short list of feeling words. End with how they could ask for the need directly.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What I did or said"}, {"id": "f2", "type": "textarea", "label": "What I felt right before the anger"}, {"id": "f3", "type": "textarea", "label": "What mattered to me in that moment"}, {"id": "f4", "type": "textarea", "label": "The need I was trying to protect"}, {"id": "f5", "type": "textarea", "label": "How I could ask for it without the heat"}, {"id": "f6", "type": "textarea", "label": "What I would like to try next time"}]'::jsonb, array['anger management', 'needs', 'communication']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('places-and-panic-avoidance-map', 'Places and Panic Avoidance Map', 'worksheet'::resource_kind, 'Charts the places and situations the client avoids because of panic and what the avoiding costs.', 'Show how avoidance has narrowed daily life and pick a first step back.', array['Adults']::text[], '25 minutes', 'Draw the map together with home at the center and mark the places that feel harder. Ask what has been given up, since the costs often matter more to the client than the fear itself. Choose one place with modest difficulty and plan an approach with a helper and an exit plan they agree to.', '[{"id": "f0", "type": "textarea", "label": "Places and situations I avoid"}, {"id": "f1", "type": "textarea", "label": "What I worry will happen there"}, {"id": "f2", "type": "textarea", "label": "What I have stopped doing because of it"}, {"id": "f3", "type": "textarea", "label": "Who or what helps me feel safer"}, {"id": "f4", "type": "textarea", "label": "One place I could approach first"}, {"id": "f5", "type": "textarea", "label": "What I will do if panic rises"}, {"id": "f6", "type": "textarea", "label": "What I learned after trying it"}]'::jsonb, array['panic attacks', 'avoidance', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('weekly-connection-planner-for-parents', 'Weekly Connection Planner for Parents', 'worksheet'::resource_kind, 'Plans small, specific moments of connection with a child across the week.', 'Make connection a planned part of the week, not a leftover.', array['Adults']::text[], '15 minutes', 'Keep the plan realistic for the family''s schedule, because ten minutes that happens beats an hour that does not. Ask the parent what their child enjoys now, not what they used to. Review which moments worked and what the child said or did in response.', '[{"id": "f0", "type": "textarea", "label": "Something my child enjoys right now"}, {"id": "f1", "type": "textarea", "label": "One moment this week I can give them my full attention"}, {"id": "f2", "type": "textarea", "label": "When and where it will happen"}, {"id": "f3", "type": "textarea", "label": "What I will put away or pause"}, {"id": "f4", "type": "textarea", "label": "A way I will show interest without correcting"}, {"id": "f5", "type": "textarea", "label": "What happened and how they responded"}, {"id": "f6", "type": "textarea", "label": "What I would like to repeat"}]'::jsonb, array['parenting', 'connection', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('visitor-and-help-boundaries-plan', 'Visitor and Help Boundaries Plan', 'worksheet'::resource_kind, 'Helps new parents decide who visits, when, and what kind of help is actually wanted.', 'Give the client a way to welcome useful help and pace the rest.', array['Adults']::text[], '20 minutes', 'Many new parents feel they cannot say no to visitors or cannot ask for what would help. Go through each person and role-play a kind, short response. Encourage specific requests such as a meal or a nap. Watch for guilt, and keep the plan flexible as needs change.', '[{"id": "f0", "type": "textarea", "label": "People who want to visit or help"}, {"id": "f1", "type": "textarea", "label": "What would truly help me right now"}, {"id": "f2", "type": "textarea", "label": "What would not help right now"}, {"id": "f3", "type": "textarea", "label": "How I will ask for the help I want"}, {"id": "f4", "type": "textarea", "label": "A kind sentence for saying not yet"}, {"id": "f5", "type": "textarea", "label": "Who I will tell first"}, {"id": "f6", "type": "textarea", "label": "What I will do if I feel overwhelmed"}]'::jsonb, array['perinatal and postpartum', 'boundaries', 'support']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('small-talk-opener-bank', 'Small Talk Opener Bank', 'worksheet'::resource_kind, 'Collects easy openers and follow-up questions the client can try in low-stakes settings.', 'Give the client ready words for starting and keeping a conversation going.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice the openers aloud in session before assigning them. Start with low-stakes settings like a cashier or neighbor. Remind the client that a short, imperfect exchange still counts as practice. Afterward, compare what they predicted with what happened.', '[{"id": "f0", "type": "textarea", "label": "Places where I could try a short chat"}, {"id": "f1", "type": "textarea", "label": "Three openers I am willing to say"}, {"id": "f2", "type": "textarea", "label": "A follow-up question I could ask"}, {"id": "f3", "type": "textarea", "label": "What I predict will happen"}, {"id": "f4", "type": "textarea", "label": "What I will do if the chat is short"}, {"id": "f5", "type": "textarea", "label": "What actually happened"}, {"id": "f6", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['social anxiety', 'communication', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('grief-energy-pacing-sheet', 'Grief Energy Pacing Sheet', 'worksheet'::resource_kind, 'Plans a week around limited energy during grief, balancing rest, tasks and connection.', 'Keep the week manageable while grief takes up energy.', array['Adults']::text[], '20 minutes', 'Grief can be tiring in ways clients do not expect, and they often judge themselves for doing less. Normalize reduced capacity and help them choose what is essential. Include one gentle way to feel connected and one rest period each day. Revisit as energy changes.', '[{"id": "f0", "type": "textarea", "label": "What has felt most tiring lately"}, {"id": "f1", "type": "textarea", "label": "What must get done this week"}, {"id": "f2", "type": "textarea", "label": "What can wait or be shared"}, {"id": "f3", "type": "textarea", "label": "How I will rest each day"}, {"id": "f4", "type": "textarea", "label": "Someone I would like to spend time with"}, {"id": "f5", "type": "textarea", "label": "Something that brings me comfort"}, {"id": "f6", "type": "textarea", "label": "How I will be kind to myself on a hard day"}]'::jsonb, array['grief and loss', 'pacing', 'self-compassion']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('safe-and-steady-daily-anchors', 'Safe and Steady Daily Anchors', 'worksheet'::resource_kind, 'Lists small daily anchors that help the client feel steady, in control and supported.', 'Build predictable, stabilizing routines that support safety day to day.', array['Adults']::text[], '20 minutes', 'Keep the focus on the present and on what helps the client feel steady, and do not ask for any details of the past. Let the client choose the anchors and the pace. If a step feels uncomfortable, adjust it or drop it. Check what they felt in their body as they practiced.', '[{"id": "f0", "type": "textarea", "label": "A morning anchor I can count on"}, {"id": "f1", "type": "textarea", "label": "A place or object that helps me feel safe"}, {"id": "f2", "type": "textarea", "label": "A grounding step I can use during the day"}, {"id": "f3", "type": "textarea", "label": "A person I can check in with"}, {"id": "f4", "type": "textarea", "label": "An evening anchor before bed"}, {"id": "f5", "type": "textarea", "label": "What I noticed when I used an anchor"}, {"id": "f6", "type": "textarea", "label": "What I want to change or drop"}]'::jsonb, array['sexual abuse', 'grounding', 'routines']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('coping-reminder-placement-plan', 'Coping Reminder Placement Plan', 'worksheet'::resource_kind, 'Decides where, when and how coping skills will be cued in the client''s daily life.', 'Put coping skills where the client will actually see them when stress hits.', array['Adults']::text[], '20 minutes', 'Skills fail most often because they are not remembered in the moment. Choose two or three cues such as a phone reminder, a card in a wallet or a note on the bathroom mirror. Test the cues for a week and swap any that blend into the background.', '[{"id": "f0", "type": "textarea", "label": "Coping skills I want to remember"}, {"id": "f1", "type": "textarea", "label": "Moments I most need them"}, {"id": "f2", "type": "textarea", "label": "Where I could place a reminder"}, {"id": "f3", "type": "textarea", "label": "A phone or alarm cue I could set"}, {"id": "f4", "type": "textarea", "label": "A person who could remind me"}, {"id": "f5", "type": "textarea", "label": "Which cue I noticed this week"}, {"id": "f6", "type": "textarea", "label": "What I will change"}]'::jsonb, array['coping skills', 'planning', 'habits']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('avoidance-workarounds-inventory', 'Avoidance Workarounds Inventory', 'worksheet'::resource_kind, 'Lists the small workarounds a client uses to dodge a feared thing and what each costs.', 'Make quiet avoidance visible so the client can choose where to loosen it.', array['Adults']::text[], '20 minutes', 'Workarounds such as taking longer routes or asking someone else to do it are easy to miss because they feel sensible. List them without criticism and rate how much each costs in time, money or freedom. Choose one to loosen first and plan a support person.', '[{"id": "f0", "type": "textarea", "label": "The feared thing or situation"}, {"id": "f1", "type": "textarea", "label": "Workarounds I use to avoid it"}, {"id": "f2", "type": "textarea", "label": "What each workaround costs me"}, {"id": "f3", "type": "textarea", "label": "What I am afraid would happen without it"}, {"id": "f4", "type": "textarea", "label": "The workaround I will loosen first"}, {"id": "f5", "type": "textarea", "label": "Who will support me"}, {"id": "f6", "type": "textarea", "label": "What happened when I tried"}]'::jsonb, array['phobias', 'avoidance', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('double-standard-technique', 'Double Standard Technique', 'cbt'::resource_kind, 'Compares the harsh way a client judges themselves with the kind way they would judge a friend.', 'Loosen self-criticism by holding the client to a fairer standard.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for a real recent situation, then have the client answer the friend question out loud before writing. Clients often say the friend is different, so ask what makes that so and treat the answer as a belief worth exploring. Keep your tone curious, not corrective.', '[{"id": "f0", "type": "textarea", "label": "The situation where I was hard on myself"}, {"id": "f1", "type": "textarea", "label": "What I said to myself, word for word"}, {"id": "f2", "type": "textarea", "label": "A friend in the same spot: what happened to them"}, {"id": "f3", "type": "textarea", "label": "What I would say to that friend"}, {"id": "f4", "type": "textarea", "label": "What is different about how I treat myself"}, {"id": "f5", "type": "textarea", "label": "A fairer sentence I could say to myself"}]'::jsonb, array['thinking traps', 'self-criticism', 'core CBT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('homework-obstacle-forecast', 'Homework Obstacle Forecast', 'cbt'::resource_kind, 'Links what was learned in session to one concrete task in the week ahead.', 'Carry a session insight into daily life with a specific, small plan.', array['Adults']::text[], '10 minutes', 'Fill it in together during the last ten minutes. Push for one task with a day and place attached, and ask the client to name what might get in the way. Open the next session with it, since review signals that between-session work matters.', '[{"id": "f0", "type": "textarea", "label": "The main idea I am taking from today"}, {"id": "f1", "type": "textarea", "label": "One thing I will try this week"}, {"id": "f2", "type": "textarea", "label": "The day, time and place I will do it"}, {"id": "f3", "type": "textarea", "label": "What might get in the way"}, {"id": "f4", "type": "textarea", "label": "What I will do if that happens"}, {"id": "f5", "type": "textarea", "label": "How I will notice if it helped"}]'::jsonb, array['homework', 'core CBT', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('thought-challenging-flashcards', 'Thought Challenging Flashcards', 'cbt'::resource_kind, 'Turns a practiced balanced thought into a pocket card to read at the moment it is needed.', 'Make the balanced response easy to reach when the old thought is loud.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the card from a thought record the client has already completed, not from scratch. Keep the balanced statement in words the client would believe on a hard day. Have them rate belief in it before and after a read-through, and revise the wording if the rating stays low.', '[{"id": "f0", "type": "textarea", "label": "The upsetting thought, as it sounds in my head"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "The facts that do not fit that thought"}, {"id": "f3", "type": "textarea", "label": "A balanced thought I can believe"}, {"id": "f4", "type": "textarea", "label": "How strongly I believe the balanced thought, 0 to 100"}, {"id": "f5", "type": "textarea", "label": "Where I will keep the card so I can reach it"}]'::jsonb, array['thought record', 'automatic thoughts', 'core CBT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('activity-barrier-problem-solving-sheet', 'Activity Barrier Problem-Solving Sheet', 'cbt'::resource_kind, 'Finds the specific obstacle behind a skipped planned activity and tests a workaround.', 'Keep activity plans moving by solving the barrier rather than blaming motivation.', array['Adults']::text[], '20 minutes', 'Use it when a planned activity was missed. Treat the miss as information about a practical or thought-based barrier, and help the client pick the smallest workaround to try. Watch for self-blame showing up as an explanation, and name it gently.', '[{"id": "f0", "type": "textarea", "label": "The activity I planned and did not do"}, {"id": "f1", "type": "textarea", "label": "What was going on right before I skipped it"}, {"id": "f2", "type": "textarea", "label": "The thought that made it feel too hard"}, {"id": "f3", "type": "textarea", "label": "A smaller version I could do"}, {"id": "f4", "type": "textarea", "label": "Something or someone that could make it easier"}, {"id": "f5", "type": "textarea", "label": "When I will try the smaller version"}]'::jsonb, array['behavioral activation', 'scheduling', 'depression']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('feelings-are-not-facts-check', 'Feelings Are Not Facts Check', 'cbt'::resource_kind, 'Separates how something feels from what the situation actually shows.', 'Help the client notice emotional reasoning and look at the facts separately.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick a moment when a strong feeling was taken as proof, such as feeling like a failure. Have the client write the feeling and the facts in separate places so the gap is visible. Expect some pushback; the aim is to hold both, not to argue the feeling away.', '[{"id": "f0", "type": "textarea", "label": "The feeling I had, and how strong it was"}, {"id": "f1", "type": "textarea", "label": "What the feeling told me was true"}, {"id": "f2", "type": "textarea", "label": "Facts that support that"}, {"id": "f3", "type": "textarea", "label": "Facts that do not fit it"}, {"id": "f4", "type": "textarea", "label": "What I might say to myself if I kept both"}, {"id": "f5", "type": "textarea", "label": "What I would do differently with that view"}]'::jsonb, array['thinking traps', 'emotional reasoning', 'core CBT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('grounding-skills-rehearsal-card', 'Grounding Skills Rehearsal Card', 'cbt'::resource_kind, 'Lets a client practice a chosen grounding skill while calm, then plan where to use it.', 'Build a reliable grounding habit before it is needed.', array['Adults']::text[], '20 minutes', 'Run it in session while the client is calm and stay with present-day practice only; it does not ask for any account of what happened. Let the client pick the skill that feels safest, rehearse it together, and adjust pacing if anything stirs up distress. Stop and ground if needed.', '[{"id": "f0", "type": "textarea", "label": "The grounding skill I chose"}, {"id": "f1", "type": "textarea", "label": "What I notice in my body when I practice it calm"}, {"id": "f2", "type": "textarea", "label": "Where I could use it this week"}, {"id": "f3", "type": "textarea", "label": "Signs that tell me I need it"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself while I use it"}, {"id": "f5", "type": "textarea", "label": "Who I could tell that I am practicing"}]'::jsonb, array['PTSD and trauma', 'grounding', 'coping skills']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('avoidance-ledger', 'Avoidance Ledger', 'cbt'::resource_kind, 'Tallies what a client avoids, what it buys in the short term and what it costs over time.', 'Show how avoidance keeps anxiety going and choose one place to start.', array['Adults']::text[], '25 minutes', 'Have the client list several avoided situations, then fill in short-term relief and long-term cost for each. Clients often see the cost column for the first time here. Pick one item together for a small first step, and leave the decision with them.', '[{"id": "f0", "type": "textarea", "label": "Something I have been avoiding"}, {"id": "f1", "type": "textarea", "label": "How it helps me right now"}, {"id": "f2", "type": "textarea", "label": "What it has cost me over time"}, {"id": "f3", "type": "textarea", "label": "Something else I avoid"}, {"id": "f4", "type": "textarea", "label": "What I am afraid would happen if I did not avoid it"}, {"id": "f5", "type": "textarea", "label": "The smallest step I could take this week"}]'::jsonb, array['anxiety', 'avoidance', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('task-start-ritual-plan', 'Task Start Ritual Plan', 'cbt'::resource_kind, 'Builds a short, repeatable routine for getting started on a task that keeps getting put off.', 'Lower the barrier to starting by making the first minutes automatic.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one task that matters to the client and design the first two minutes in detail, including where to sit and what to open. Keep it small enough to feel almost silly. Check in next session on whether the ritual was used, not whether the task finished.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "What gets in the way right at the start"}, {"id": "f2", "type": "textarea", "label": "My first two-minute action"}, {"id": "f3", "type": "textarea", "label": "Where and when I will do it"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself when I want to delay"}, {"id": "f5", "type": "textarea", "label": "A reward or signal that I started"}]'::jsonb, array['ADHD', 'task initiation', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('high-risk-situation-rehearsal-plan', 'High-Risk Situation Rehearsal Plan', 'cbt'::resource_kind, 'Walks through an upcoming situation where substance use urges are likely and rehearses responses.', 'Prepare specific responses for urges before a risky situation arrives.', array['Adults']::text[], '30 minutes', 'Choose a real upcoming situation in the next week or two and rehearse it in session, including the moment an offer or urge appears. Let the client name the plan; your role is to ask what could go wrong with it. Keep the tone practical and free of blame.', '[{"id": "f0", "type": "textarea", "label": "The situation coming up"}, {"id": "f1", "type": "textarea", "label": "Who or what will be there"}, {"id": "f2", "type": "textarea", "label": "Urges I expect, and when they may peak"}, {"id": "f3", "type": "textarea", "label": "What I will say or do in that moment"}, {"id": "f4", "type": "textarea", "label": "Who I can contact if the urge gets strong"}, {"id": "f5", "type": "textarea", "label": "How I will leave or change plans if I need to"}, {"id": "f6", "type": "textarea", "label": "What I will do afterward"}]'::jsonb, array['addiction', 'urges', 'relapse prevention']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('anger-aftermath-repair-sheet', 'Anger Aftermath Repair Sheet', 'cbt'::resource_kind, 'Guides a client through what to do after an angry episode, from calming down to repair.', 'Turn the aftermath of anger into a step toward repair.', array['Adults']::text[], '20 minutes', 'Use it after a recent episode once the client is calm, not in the heat of it. Keep the focus on what the client can own and what repair looks like, without making the client wrong as a person. Note the thoughts that kept the anger going for next time.', '[{"id": "f0", "type": "textarea", "label": "What happened, in a sentence or two"}, {"id": "f1", "type": "textarea", "label": "The thought that fed my anger most"}, {"id": "f2", "type": "textarea", "label": "What I did that I wish I had done differently"}, {"id": "f3", "type": "textarea", "label": "What I want the other person to know"}, {"id": "f4", "type": "textarea", "label": "A repair step I can take, and when"}, {"id": "f5", "type": "textarea", "label": "What I will do sooner next time"}]'::jsonb, array['anger management', 'repair', 'thinking traps']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('panic-avoidance-ladder', 'Panic Avoidance Ladder', 'cbt'::resource_kind, 'Ranks places and activities a client avoids for fear of panic, from easiest to hardest.', 'Plan gradual return to avoided places and activities.', array['Adults']::text[], '30 minutes', 'Build the ladder with the client and rate each step for expected fear. Start with a step they rate about moderate so practice stays manageable, and plan to repeat it until fear falls before moving up. Check on safety behaviors that can creep back in.', '[{"id": "f0", "type": "textarea", "label": "Places or activities I avoid because of panic"}, {"id": "f1", "type": "textarea", "label": "How anxious each one feels, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "The easiest step I could practice first"}, {"id": "f3", "type": "textarea", "label": "What I am afraid will happen"}, {"id": "f4", "type": "textarea", "label": "Safety behaviors I might use, and how I will drop them"}, {"id": "f5", "type": "textarea", "label": "How I will know the step went well"}]'::jsonb, array['panic attacks', 'exposure', 'hierarchy']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('parent-expectation-check-sheet', 'Parent Expectation Check Sheet', 'cbt'::resource_kind, 'Helps a parent compare their expectations of a child with what is realistic for the child''s age.', 'Soften expectations that fuel parental frustration and guilt.', array['Adults']::text[], '20 minutes', 'Use it with a parent who feels constantly let down by their child''s behavior. Ask about the source of each expectation, often a family rule or an old belief about good parenting. Keep it supportive; parents often arrive feeling judged already.', '[{"id": "f0", "type": "textarea", "label": "A moment this week when I felt frustrated"}, {"id": "f1", "type": "textarea", "label": "What I expected my child to do"}, {"id": "f2", "type": "textarea", "label": "Where I learned that expectation"}, {"id": "f3", "type": "textarea", "label": "What my child might be able to do at their age"}, {"id": "f4", "type": "textarea", "label": "A fairer expectation for next time"}, {"id": "f5", "type": "textarea", "label": "How I will tell my child what I need"}]'::jsonb, array['parenting', 'core beliefs', 'thinking traps']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('balanced-self-appraisal-sheet', 'Balanced Self-Appraisal Sheet', 'cbt'::resource_kind, 'Lists strengths and shortcomings side by side so a client can describe themselves fairly.', 'Replace all-or-nothing self-ratings with a balanced, specific description.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client fill in the strengths column first and accept only specific examples, not general claims. Expect the list of flaws to come easily and keep it to specifics too. The last prompt is the point: a fairer sentence the client would actually stand behind.', '[{"id": "f0", "type": "textarea", "label": "A quality I like about myself, with an example"}, {"id": "f1", "type": "textarea", "label": "A quality I do not like, with an example"}, {"id": "f2", "type": "textarea", "label": "A time my shortcoming did not matter as much as I expected"}, {"id": "f3", "type": "textarea", "label": "What people who know me well might add"}, {"id": "f4", "type": "textarea", "label": "How I sum myself up now"}, {"id": "f5", "type": "textarea", "label": "A fairer way to sum myself up"}]'::jsonb, array['self-esteem', 'core beliefs', 'evidence log']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('conversation-experiment-planner', 'Conversation Experiment Planner', 'cbt'::resource_kind, 'Sets up a small social experiment, such as asking a question, and records what actually happened.', 'Test social fears with a planned, specific conversation.', array['Adults']::text[], '25 minutes', 'Pick one small conversation the client can do this week and write the fear as a specific prediction. Ask the client to drop one safety behavior during it if ready. Review what actually happened, including what went better than expected.', '[{"id": "f0", "type": "textarea", "label": "The conversation I will try"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "How sure I am, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "One safety behavior I will try dropping"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I learned about my prediction"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'evidence']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('grief-wave-coping-plan', 'Grief Wave Coping Plan', 'cbt'::resource_kind, 'Helps a grieving client prepare for waves of feeling on hard days and dates.', 'Plan ahead for hard moments so grief feels less like an ambush.', array['Adults']::text[], '25 minutes', 'Ask about dates, places and moments that tend to bring a wave, and plan for them together. Let grief be grief; the plan is for support and pacing, not for getting rid of feeling. Include one thing the client can do for themselves and one person to reach.', '[{"id": "f0", "type": "textarea", "label": "A day or moment I expect to be hard"}, {"id": "f1", "type": "textarea", "label": "What the wave usually feels like in my body"}, {"id": "f2", "type": "textarea", "label": "A thought that often comes with it"}, {"id": "f3", "type": "textarea", "label": "One thing that helps me get through it"}, {"id": "f4", "type": "textarea", "label": "A person I can reach out to"}, {"id": "f5", "type": "textarea", "label": "One way I can honor the person I lost"}]'::jsonb, array['grief and loss', 'coping skills', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('safe-support-circle-plan', 'Safe Support Circle Plan', 'cbt'::resource_kind, 'Maps the people and places that feel safe and what a client wants from each.', 'Strengthen present-day support and pacing for recovery.', array['Adults']::text[], '25 minutes', 'Keep this about safety and support now; it never asks for any account of what happened. Let the client decide who goes on the map and what they want to share with each person, including nothing. Revisit it as trust changes. If the client is at risk, use 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "A person or place where I feel safe"}, {"id": "f1", "type": "textarea", "label": "What I can ask of them"}, {"id": "f2", "type": "textarea", "label": "What I do not want to share yet"}, {"id": "f3", "type": "textarea", "label": "A sign that I need more support"}, {"id": "f4", "type": "textarea", "label": "A small step I can take to connect this week"}, {"id": "f5", "type": "textarea", "label": "What I will do if I feel unsafe"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-match-sheet', 'Coping Toolbox Match Sheet', 'cbt'::resource_kind, 'Matches specific coping skills to the situations and feelings they fit best.', 'Choose the right coping skill for the moment instead of one for everything.', array['Adults']::text[], '25 minutes', 'Have the client name three recent hard moments and pick a skill for each, noting whether it fit. Clients often rely on one tool and then call it useless when it fails. Highlight a mismatch as useful information, not a failure.', '[{"id": "f0", "type": "textarea", "label": "A recent hard moment"}, {"id": "f1", "type": "textarea", "label": "What I felt, and how strong it was"}, {"id": "f2", "type": "textarea", "label": "The skill I used, if any"}, {"id": "f3", "type": "textarea", "label": "How well it fit, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "A skill that might fit better"}, {"id": "f5", "type": "textarea", "label": "When I will try it next"}]'::jsonb, array['coping skills', 'self-monitoring', 'core CBT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('values-beyond-appearance-plan', 'Values Beyond Appearance Plan', 'cbt'::resource_kind, 'Connects a client''s values to daily activities that do not depend on how they look.', 'Shift attention and time from appearance toward what the client values.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client would do with more time and attention if appearance mattered less, and build from their answer. Keep the plan concrete, with a day and a place. Do not debate how they look; redirect to what they value and what they want to do next.', '[{"id": "f0", "type": "textarea", "label": "Something I value that has nothing to do with looks"}, {"id": "f1", "type": "textarea", "label": "A time I felt like myself"}, {"id": "f2", "type": "textarea", "label": "An activity I avoid because of how I feel about my appearance"}, {"id": "f3", "type": "textarea", "label": "A small step toward that activity"}, {"id": "f4", "type": "textarea", "label": "What I might tell myself when appearance thoughts show up"}, {"id": "f5", "type": "textarea", "label": "Who could do this with me"}]'::jsonb, array['body image', 'values', 'behavioral activation']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('hooked-and-unhooked-log', 'Hooked and Unhooked Log', 'act'::resource_kind, 'Tracks moments the client got pulled along by a thought or feeling, and the moment they noticed.', 'Build the skill of noticing being hooked and choosing a next step.', array['Adults', 'Teens']::text[], 'One week', 'Introduce hooks as anything that pulls a person away from what matters, with no moral weight on it. Ask for small, recent examples so the log stays light. The win is the noticing, however late, so celebrate a late catch as much as an early one, and look for the most common hook across the week.', '[{"id": "f0", "type": "textarea", "label": "What was going on when I got hooked"}, {"id": "f1", "type": "textarea", "label": "What the hook was (a thought, a feeling, an urge to act)"}, {"id": "f2", "type": "textarea", "label": "What I did while hooked"}, {"id": "f3", "type": "textarea", "label": "The moment I noticed, and what told me"}, {"id": "f4", "type": "textarea", "label": "One small thing I could do next time to unhook"}, {"id": "f5", "type": "textarea", "label": "What I would rather be doing with this moment"}]'::jsonb, array['values', 'defusion', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('clean-and-dirty-discomfort-sort', 'Clean and Dirty Discomfort Sort', 'act'::resource_kind, 'Sorts a client''s distress into the pain that comes with caring and the extra pain added by struggling.', 'Separate unavoidable discomfort from the struggle layered on top of it.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through one recent painful situation and sort each reaction into clean (the natural hurt) or dirty (what the fight against it added). Clients often file everything as dirty or everything as clean, so go slowly and let the client decide. It pairs well with willingness work afterward.', '[{"id": "f0", "type": "textarea", "label": "A recent situation that hurt"}, {"id": "f1", "type": "textarea", "label": "The natural feelings that came up, the clean part"}, {"id": "f2", "type": "textarea", "label": "What I did to get rid of those feelings"}, {"id": "f3", "type": "textarea", "label": "What the struggle added, the dirty part"}, {"id": "f4", "type": "textarea", "label": "What it cost me to fight the feeling"}, {"id": "f5", "type": "textarea", "label": "What I could do with the clean part instead"}]'::jsonb, array['acceptance', 'willingness', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('eulogy-values-exercise', 'Eulogy Values Exercise', 'act'::resource_kind, 'Invites the client to imagine how they hope to be remembered, then turns it into values.', 'Surface values the client cares about most through a longer view.', array['Adults']::text[], '25 minutes', 'Some clients find this moving and some find it heavy, so offer it as an imagined exercise and let them pace it. Keep the focus on qualities and actions rather than achievements, and stay with the client if grief surfaces. If a client mentions hopelessness or wanting to die, stop and follow your own risk process.', '[{"id": "f0", "type": "textarea", "label": "What I hope people would say about how I treated them"}, {"id": "f1", "type": "textarea", "label": "What I hope they would say I stood for"}, {"id": "f2", "type": "textarea", "label": "Qualities I want to be known for"}, {"id": "f3", "type": "textarea", "label": "Where my life today matches this"}, {"id": "f4", "type": "textarea", "label": "Where my life today does not match this"}, {"id": "f5", "type": "textarea", "label": "One small action this week that moves toward it"}]'::jsonb, array['values', 'life review', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('hexaflex-flexibility-snapshot', 'Hexaflex Flexibility Snapshot', 'act'::resource_kind, 'A one-page picture of where a client feels flexible or stuck across the six ACT processes.', 'Give client and clinician a shared map of where to focus next.', array['Adults']::text[], '30 minutes', 'Use plain language for each of the six processes and have the client rate how free or stuck they feel in each one on a simple scale. It is a conversation starter rather than a score, and the ratings shift from week to week. Revisit it every few sessions to see what has moved.', '[{"id": "f0", "type": "textarea", "label": "How free or stuck I feel with my thoughts, and an example"}, {"id": "f1", "type": "textarea", "label": "How willing I am to have hard feelings, and an example"}, {"id": "f2", "type": "textarea", "label": "How present I am in my day, and an example"}, {"id": "f3", "type": "textarea", "label": "How much I notice myself as more than my story"}, {"id": "f4", "type": "textarea", "label": "How clear I am on what matters to me"}, {"id": "f5", "type": "textarea", "label": "How much I act on what matters to me"}, {"id": "f6", "type": "textarea", "label": "The area I most want to work on first"}]'::jsonb, array['hexaflex', 'psychoeducation', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('everyday-task-mindfulness-practice', 'Everyday Task Mindfulness Practice', 'act'::resource_kind, 'Turns one routine task into a daily practice of full attention and gentle returning.', 'Practice present-moment contact inside ordinary life.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Pick a task the client already does, such as washing dishes or brushing teeth, and have them do it with full attention to sights, sounds and touch. The mind will wander, and each return is the practice. Watch for clients who turn it into a test they can fail.', '[{"id": "f0", "type": "textarea", "label": "The task I chose"}, {"id": "f1", "type": "textarea", "label": "What I noticed with my senses"}, {"id": "f2", "type": "textarea", "label": "Where my mind went"}, {"id": "f3", "type": "textarea", "label": "How I brought my attention back"}, {"id": "f4", "type": "textarea", "label": "What was different about this task with my full attention"}, {"id": "f5", "type": "textarea", "label": "Another task I could try next"}]'::jsonb, array['mindfulness', 'present moment', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('sounds-around-me-anchor-practice', 'Sounds Around Me Anchor Practice', 'act'::resource_kind, 'A short listening exercise that helps a client stay in the present through what they can hear.', 'Offer a steady, low-risk way to stay connected to the here and now.', array['Adults']::text[], 'Five minutes', 'Keep this brief and let the client keep their eyes open and stop at any time. Sounds in the room are a gentle entry point and need no talk about what happened. Practice in session first so it is familiar before the client tries it at home, and watch for any rise in distress.', '[{"id": "f0", "type": "textarea", "label": "Sounds I can hear that are close to me"}, {"id": "f1", "type": "textarea", "label": "Sounds I can hear that are far away"}, {"id": "f2", "type": "textarea", "label": "One sound that feels neutral or pleasant"}, {"id": "f3", "type": "textarea", "label": "Where I feel steadier in my body while I listen"}, {"id": "f4", "type": "textarea", "label": "A place or time this week I could use this practice"}, {"id": "f5", "type": "textarea", "label": "Who or what reminds me I am here now"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('worry-hands-defusion-exercise', 'Worry Hands Defusion Exercise', 'act'::resource_kind, 'Uses the hands held over the eyes and then held away to show how thoughts pull focus.', 'Let anxious clients feel the difference between fusing with worry and noticing it.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client cover their face with their hands as if they were a worry and try to talk or look around, then lower them to the lap. Ask what changed. Many clients grasp defusion more from this than from explanation, so allow time to discuss, and run it with one real worry.', '[{"id": "f0", "type": "textarea", "label": "A worry that shows up often"}, {"id": "f1", "type": "textarea", "label": "What it was like holding it up close"}, {"id": "f2", "type": "textarea", "label": "What it was like holding it at a distance"}, {"id": "f3", "type": "textarea", "label": "What I could still do with the worry in my lap"}, {"id": "f4", "type": "textarea", "label": "What matters to me that the worry gets in the way of"}, {"id": "f5", "type": "textarea", "label": "Where I could practice this in daily life"}]'::jsonb, array['anxiety', 'defusion', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('values-reminder-sticky-notes-plan', 'Values Reminder Sticky Notes Plan', 'act'::resource_kind, 'Places short values-based cues where a client with attention difficulties will meet them.', 'Connect daily tasks to what matters so starting feels worth it.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients with attention challenges often know what to do but lose the why in the moment. Draft two or three short cues tied to real places such as a desk, a door or a phone. Keep the wording personal and change the cues when they become invisible.', '[{"id": "f0", "type": "textarea", "label": "Something I keep putting off that matters to me"}, {"id": "f1", "type": "textarea", "label": "Why it matters, in a few words"}, {"id": "f2", "type": "textarea", "label": "A short cue I could write"}, {"id": "f3", "type": "textarea", "label": "Where I will place it so I see it"}, {"id": "f4", "type": "textarea", "label": "What I want to be doing when I see it"}, {"id": "f5", "type": "textarea", "label": "When I will change the cue to keep it fresh"}]'::jsonb, array['ADHD', 'values', 'task initiation']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('urge-bubble-watching-practice', 'Urge Bubble Watching Practice', 'act'::resource_kind, 'Pictures an urge as a bubble that rises, floats and pops, with a short log of what happened.', 'Help clients ride out urges without acting on them.', array['Adults']::text[], '10 minutes', 'Frame substance use urges as passing events the client can watch without acting. Practice in session with a mild urge before using it for stronger ones, and talk about the urge rising and falling. If urges feel overwhelming, return to your own safety plan and supports.', '[{"id": "f0", "type": "textarea", "label": "The urge and what set it off"}, {"id": "f1", "type": "textarea", "label": "Where I noticed it in my body"}, {"id": "f2", "type": "textarea", "label": "What the bubble looked like as it grew"}, {"id": "f3", "type": "textarea", "label": "What happened as I watched it"}, {"id": "f4", "type": "textarea", "label": "How long it lasted"}, {"id": "f5", "type": "textarea", "label": "What I did next that fit what matters to me"}]'::jsonb, array['addiction', 'urges', 'mindfulness']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('doubt-radio-practice', 'Doubt Radio Practice', 'act'::resource_kind, 'Treats intrusive doubt as background radio the client can hear while still acting on values.', 'Practice carrying doubt along instead of answering it.', array['Adults', 'Teens']::text[], '10 minutes', 'Clients with intrusive thoughts often try to argue the radio into silence. Have them name the station, turn the volume down in imagination, and then do a chosen task. Avoid reassurance during the exercise, and expect the doubt to keep playing.', '[{"id": "f0", "type": "textarea", "label": "What the doubt radio says"}, {"id": "f1", "type": "textarea", "label": "What I usually do to make it stop"}, {"id": "f2", "type": "textarea", "label": "What happens to the doubt when I do that"}, {"id": "f3", "type": "textarea", "label": "What I could do while the radio keeps playing"}, {"id": "f4", "type": "textarea", "label": "What matters to me that I am skipping"}, {"id": "f5", "type": "textarea", "label": "How it went when I let it play"}]'::jsonb, array['OCD', 'defusion', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('panic-welcome-mat-practice', 'Panic Welcome Mat Practice', 'act'::resource_kind, 'Practices welcoming panic sensations like a visitor rather than pushing them out.', 'Shift a client''s relationship with panic from fighting it to allowing it.', array['Adults']::text[], '15 minutes', 'Start with a mild sensation in session and use a welcoming phrase such as ''here you are''. The aim is not to make the panic go away, which clients will try to use it for, so name that gently. Follow with a short debrief about what shifted.', '[{"id": "f0", "type": "textarea", "label": "Sensations I notice when panic shows up"}, {"id": "f1", "type": "textarea", "label": "What I usually do to push them away"}, {"id": "f2", "type": "textarea", "label": "A welcoming phrase I could try"}, {"id": "f3", "type": "textarea", "label": "What happened when I let them be there"}, {"id": "f4", "type": "textarea", "label": "What I want to keep doing while they are there"}, {"id": "f5", "type": "textarea", "label": "When I will practice this again"}]'::jsonb, array['panic attacks', 'acceptance', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('hooked-parent-reset-card', 'Hooked Parent Reset Card', 'act'::resource_kind, 'A quick card for catching a parenting hook and returning to the parent the client wants to be.', 'Give parents a short pause and values check in heated moments.', array['Adults']::text[], '15 minutes', 'Have the parent name their typical hooks, such as thoughts of failing or urges to yell, and the parent they want to be in those moments. Keep the card small enough to live on a fridge or phone. Normalize that resets happen after the fact too.', '[{"id": "f0", "type": "textarea", "label": "A moment I got hooked with my child"}, {"id": "f1", "type": "textarea", "label": "The thought or feeling that hooked me"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "The parent I want to be in that moment"}, {"id": "f4", "type": "textarea", "label": "A pause I could take, in a few words"}, {"id": "f5", "type": "textarea", "label": "One thing I could say or do next time"}]'::jsonb, array['parenting', 'values', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('worth-without-proof-practice', 'Worth Without Proof Practice', 'act'::resource_kind, 'Practices holding worth as a given rather than something to be earned or proven.', 'Loosen the link between achievements and a person''s sense of worth.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients with low self-esteem often collect evidence for and against themselves. Invite them to step out of the courtroom and ask what it would be like to treat worth as not up for debate. Expect resistance and go slowly.', '[{"id": "f0", "type": "textarea", "label": "What I usually try to prove about myself"}, {"id": "f1", "type": "textarea", "label": "Who I am trying to prove it to"}, {"id": "f2", "type": "textarea", "label": "What it costs me to keep proving it"}, {"id": "f3", "type": "textarea", "label": "What I would do if my worth were not in question"}, {"id": "f4", "type": "textarea", "label": "A small action this week that fits that"}, {"id": "f5", "type": "textarea", "label": "What kind words I would say to a friend in my place"}]'::jsonb, array['self-esteem', 'self-compassion', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('willing-in-the-room-plan', 'Willing in the Room Plan', 'act'::resource_kind, 'Plans a social situation around what the client is willing to feel rather than how to avoid it.', 'Help clients move toward people while anxiety comes along.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one small social step linked to something the client cares about. Ask what they are willing to feel to do it, and avoid promises that the anxiety will fade. Review afterward for what mattered, not how anxious they felt.', '[{"id": "f0", "type": "textarea", "label": "A social step that matters to me"}, {"id": "f1", "type": "textarea", "label": "What I am afraid will happen"}, {"id": "f2", "type": "textarea", "label": "What I am willing to feel to do it"}, {"id": "f3", "type": "textarea", "label": "How I will bring my attention to the other person"}, {"id": "f4", "type": "textarea", "label": "What I will do if anxiety rises"}, {"id": "f5", "type": "textarea", "label": "How it went and what I learned"}]'::jsonb, array['social anxiety', 'willingness', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('relationship-hooks-noticing-sheet', 'Relationship Hooks Noticing Sheet', 'act'::resource_kind, 'Helps a client spot the thoughts and urges that pull them into conflict or withdrawal with someone close.', 'Notice relationship hooks early and choose a response that fits their values.', array['Adults']::text[], '20 minutes', 'Use a recent, low-intensity exchange and trace the hook, the automatic response, and the alternative that fits the partner the client wants to be. Clients sometimes use it to prove the other person wrong, so keep it on their own behavior.', '[{"id": "f0", "type": "textarea", "label": "A recent exchange that went badly"}, {"id": "f1", "type": "textarea", "label": "The thought or feeling that hooked me"}, {"id": "f2", "type": "textarea", "label": "What I did in response"}, {"id": "f3", "type": "textarea", "label": "What I would like my response to stand for"}, {"id": "f4", "type": "textarea", "label": "One different response I could try"}, {"id": "f5", "type": "textarea", "label": "How I could tell the other person what I am working on"}]'::jsonb, array['relationship issues', 'values', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('safe-now-anchor-phrases-sheet', 'Safe Now Anchor Phrases Sheet', 'act'::resource_kind, 'Builds a short set of present-tense phrases that remind a client where they are and that they have choices.', 'Give the client a steady set of words for staying present.', array['Adults']::text[], '15 minutes', 'Work in session, at the client''s pace, and never ask for details of what happened. Phrases should be in the client''s own words and describe the present, such as the room, the date and who is near. Stop or shift if the client seems flooded, and be mindful of reporting duties where they apply.', '[{"id": "f0", "type": "textarea", "label": "Where I am right now"}, {"id": "f1", "type": "textarea", "label": "Today''s date and what I can see that shows it"}, {"id": "f2", "type": "textarea", "label": "One thing that is different now"}, {"id": "f3", "type": "textarea", "label": "A person or place that feels steady"}, {"id": "f4", "type": "textarea", "label": "A phrase that helps me stay here"}, {"id": "f5", "type": "textarea", "label": "What I will do if the phrase does not help"}]'::jsonb, array['sexual abuse', 'grounding', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('coping-skill-trial-run-sheet', 'Coping Skill Trial Run Sheet', 'act'::resource_kind, 'Lets a client test a coping skill in a real moment and review what it did for them.', 'Match coping skills to the moments and values where they help.', array['Adults', 'Teens']::text[], 'One week', 'Have the client pick one skill and one situation, then log what happened without judging it. A skill that fails is useful data, so ask what it gave them and what it cost. Follow with a review in session and decide whether to keep it, adjust it or swap it.', '[{"id": "f0", "type": "textarea", "label": "The skill I tried"}, {"id": "f1", "type": "textarea", "label": "The situation where I used it"}, {"id": "f2", "type": "textarea", "label": "What I felt before and after"}, {"id": "f3", "type": "textarea", "label": "What the skill helped me do"}, {"id": "f4", "type": "textarea", "label": "What it cost me or got in the way of"}, {"id": "f5", "type": "textarea", "label": "Whether I will keep, change or swap it"}]'::jsonb, array['coping skills', 'workability', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('body-in-motion-values-walk', 'Body in Motion Values Walk', 'act'::resource_kind, 'A gentle walk or movement practice that links what the body can do to what the client cares about.', 'Move attention from appearance to function and values.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to walk or move and notice what the body does for them, such as carrying them to people and places they care about. Keep the focus on experience and meaning, never on how the body looks. Stay curious if judgments surface, and let the client set the pace.', '[{"id": "f0", "type": "textarea", "label": "What my body let me do today"}, {"id": "f1", "type": "textarea", "label": "A place or person my body takes me to"}, {"id": "f2", "type": "textarea", "label": "A kind word I could say to my body"}, {"id": "f3", "type": "textarea", "label": "A judgment that showed up and what I did with it"}, {"id": "f4", "type": "textarea", "label": "A valued activity I want to do this week"}, {"id": "f5", "type": "textarea", "label": "How I felt after the walk"}]'::jsonb, array['body image', 'values', 'core ACT']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('one-mindfully-single-task-practice', 'One-Mindfully Single Task Practice', 'dbt'::resource_kind, 'Guides the client through doing one everyday task with full attention and noting each drift.', 'Build the habit of one thing at a time and gently returning attention.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick a low-stakes task such as washing a cup or folding laundry and run it in session first. Clients tend to judge each drift as failure, so count the returns instead of the drifts. Ask about the pace of the task afterward, since rushing often shows up before the client notices it.', '[{"id": "f0", "type": "textarea", "label": "The one task I chose to do with full attention"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my hands, eyes, and body while doing it"}, {"id": "f2", "type": "textarea", "label": "How many times my mind wandered, and where it went"}, {"id": "f3", "type": "textarea", "label": "What I said to myself when I noticed, and what I will say next time"}, {"id": "f4", "type": "textarea", "label": "One more everyday task I could try this week"}]'::jsonb, array['mindfulness', 'one-mindfully', 'skills']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-commitment-log', 'Turning the Mind Commitment Log', 'dbt'::resource_kind, 'Tracks the moments a client notices resistance and chooses to turn toward acceptance again.', 'Practice re-committing to acceptance each time resistance returns.', array['Adults']::text[], 'One week', 'Explain that turning the mind is a choice made again and again, not a single decision. Review the log for times when resistance showed up with a body cue, since that cue is often the most useful early signal. Keep the tone curious and avoid treating repeated entries as setbacks.', '[{"id": "f0", "type": "textarea", "label": "The situation where I noticed I was resisting"}, {"id": "f1", "type": "textarea", "label": "What resistance felt like in my body"}, {"id": "f2", "type": "textarea", "label": "The words I used to turn my mind toward acceptance"}, {"id": "f3", "type": "textarea", "label": "What I did next, even if it was small"}, {"id": "f4", "type": "textarea", "label": "What got in the way of turning my mind today"}, {"id": "f5", "type": "textarea", "label": "What I want to try again tomorrow"}]'::jsonb, array['acceptance', 'willingness', 'radical acceptance']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('describe-the-emotion-ladder', 'Describe the Emotion Ladder', 'dbt'::resource_kind, 'Helps a client move from one broad feeling word to more precise words for what is happening.', 'Name emotions with more precision so they can be understood and handled.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients start with words like bad or stressed. Work up the ladder slowly and let them reject words that do not fit. Precise naming tends to lower the pressure on its own, so pause to notice any shift before moving on. Keep a short list of their own words for next time.', '[{"id": "f0", "type": "textarea", "label": "The broad word I started with"}, {"id": "f1", "type": "textarea", "label": "Three more specific words that might fit"}, {"id": "f2", "type": "textarea", "label": "The words that fit best and where I feel them in my body"}, {"id": "f3", "type": "textarea", "label": "What set this feeling off"}, {"id": "f4", "type": "textarea", "label": "What the feeling seems to be telling me"}, {"id": "f5", "type": "textarea", "label": "How strong it is on a scale of 0 to 10 right now"}]'::jsonb, array['emotion regulation', 'skills', 'naming emotions']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('problem-solving-steps-sheet', 'Problem-Solving Steps Sheet', 'dbt'::resource_kind, 'Walks a client through defining a problem, listing options, and testing one choice.', 'Move from feeling stuck to one concrete step the client is willing to try.', array['Adults']::text[], '30 minutes', 'Use it when a client keeps circling the same situation. Check first whether the problem can be solved or whether it calls for acceptance or emotion skills instead. Most clients name too many options too soon, so keep the focus on one choice and plan how they will review it afterward.', '[{"id": "f0", "type": "textarea", "label": "The problem, stated in one or two plain sentences"}, {"id": "f1", "type": "textarea", "label": "What I can change and what I cannot"}, {"id": "f2", "type": "textarea", "label": "Three or more options, even ones that seem unlikely"}, {"id": "f3", "type": "textarea", "label": "The pros and cons of my top two options"}, {"id": "f4", "type": "textarea", "label": "The option I will try and when"}, {"id": "f5", "type": "textarea", "label": "How I will know whether it helped"}, {"id": "f6", "type": "textarea", "label": "What I will do if it does not"}]'::jsonb, array['problem solving', 'skills', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('weekly-skills-review-sheet', 'Weekly Skills Review Sheet', 'dbt'::resource_kind, 'Gives client and clinician a short, structured look back at which skills were used and what happened.', 'Spot which skills helped, which did not, and what to practice next.', array['Adults', 'Teens']::text[], '15 minutes', 'Open the session with this so the review has a steady place. Focus on what the client tried, not on how well it worked, and ask about skills they skipped without judgment. Patterns across weeks are usually more useful than any single day.', '[{"id": "f0", "type": "textarea", "label": "Skills I used this week"}, {"id": "f1", "type": "textarea", "label": "A time a skill helped and what it did"}, {"id": "f2", "type": "textarea", "label": "A time I wanted to use a skill but did not"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "A skill I want to practice more next week"}, {"id": "f5", "type": "textarea", "label": "Support I would like from my clinician"}]'::jsonb, array['skills', 'review', 'diary card']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('safe-place-imagery-card', 'Safe Place Imagery Card', 'dbt'::resource_kind, 'Builds a calm, personal place in the mind that a client can return to for stabilizing.', 'Give the client a steady, practiced place to settle when distress rises.', array['Adults']::text[], '25 minutes', 'Build this slowly, in session, with the client in charge of every detail and free to stop at any point. Choose a place that is neutral or pleasant, and never ask about distressing memories. If the image brings up unease, change it or switch to grounding. Practice short and often.', '[{"id": "f0", "type": "textarea", "label": "Where my safe place is, real or imagined"}, {"id": "f1", "type": "textarea", "label": "What I see there"}, {"id": "f2", "type": "textarea", "label": "What I hear and smell there"}, {"id": "f3", "type": "textarea", "label": "What my body feels like there"}, {"id": "f4", "type": "textarea", "label": "A word or phrase that brings me back to it"}, {"id": "f5", "type": "textarea", "label": "When I will practice this during the week"}, {"id": "f6", "type": "textarea", "label": "What I will do if the image stops feeling safe"}]'::jsonb, array['PTSD and trauma', 'grounding', 'imagery', 'safety']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('low-energy-day-skills-menu', 'Low Energy Day Skills Menu', 'dbt'::resource_kind, 'Lists small, doable skills matched to days when energy and motivation are very low.', 'Keep a few manageable actions available on the hardest days.', array['Adults']::text[], '20 minutes', 'Build the menu together when the client is having a steadier day. Keep every item small enough to finish in a few minutes, such as opening a curtain or drinking water. Clients often set items too large, so trim them together. If low mood is deepening, use your clinical judgment about next steps.', '[{"id": "f0", "type": "textarea", "label": "Three tiny actions I can do in under five minutes"}, {"id": "f1", "type": "textarea", "label": "One skill that helps my body, such as moving or a warm shower"}, {"id": "f2", "type": "textarea", "label": "One skill that helps me reach another person"}, {"id": "f3", "type": "textarea", "label": "One thing I can let go of for today"}, {"id": "f4", "type": "textarea", "label": "Words I can say to myself on a low-energy day"}, {"id": "f5", "type": "textarea", "label": "Who I could tell if the day stays heavy"}, {"id": "f6", "type": "textarea", "label": "How I will know the menu helped"}]'::jsonb, array['depression', 'behavioral activation', 'coping skills']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('pause-before-acting-card', 'Pause Before Acting Card', 'dbt'::resource_kind, 'Sets up a short, practiced pause between an impulse and the action that follows it.', 'Create a small gap between impulse and action that the client can use.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the pause short and concrete so it fits real life, such as three breaths or counting to ten. Rehearse it in session with a recent impulsive moment. Clients with attention difficulties often do better with a visible cue, so plan where the card will live.', '[{"id": "f0", "type": "textarea", "label": "An impulse that got me into trouble recently"}, {"id": "f1", "type": "textarea", "label": "What I notice in my body just before I act"}, {"id": "f2", "type": "textarea", "label": "My pause, in plain words, such as three breaths"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card so I see it"}, {"id": "f4", "type": "textarea", "label": "What I will do after the pause"}, {"id": "f5", "type": "textarea", "label": "Who can remind me to use it"}, {"id": "f6", "type": "textarea", "label": "What happened the last time I paused"}]'::jsonb, array['ADHD', 'impulsivity', 'distress tolerance']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('adaptive-denial-script-card', 'Adaptive Denial Script Card', 'dbt'::resource_kind, 'Helps a client rehearse putting a substance use urge out of mind and moving to another task.', 'Practice setting an urge aside for now and redirecting attention.', array['Adults']::text[], '20 minutes', 'Explain that this is a short-term skill for moments when an urge is loud, not a way of pretending the urge is absent. Rehearse the script aloud and choose a task that fully occupies the hands. Review with the client what worked and what did not, and keep the language free of labels.', '[{"id": "f0", "type": "textarea", "label": "A situation where substance use urges are strong"}, {"id": "f1", "type": "textarea", "label": "The words I will say to myself to put the urge aside for now"}, {"id": "f2", "type": "textarea", "label": "The task I will move to"}, {"id": "f3", "type": "textarea", "label": "Who I can contact if the urge stays strong"}, {"id": "f4", "type": "textarea", "label": "What I will do if the urge keeps rising"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself after the urge passes"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('thought-observing-practice-log', 'Thought Observing Practice Log', 'dbt'::resource_kind, 'Trains a client to watch intrusive thoughts come and go without arguing with them or acting on them.', 'Practice noticing a thought as a thought, without a ritual or reply.', array['Adults']::text[], 'Five minutes daily', 'Explain that the aim is to notice, not to make thoughts stop. Model a light, curious label such as there is that thought again. Clients may turn the practice into a hidden way of seeking certainty, so check how it is going and keep sessions brief.', '[{"id": "f0", "type": "textarea", "label": "The thought I noticed"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body when it showed up"}, {"id": "f2", "type": "textarea", "label": "The label I gave it"}, {"id": "f3", "type": "textarea", "label": "What I did instead of replying or acting on it"}, {"id": "f4", "type": "textarea", "label": "How long it took before my attention moved on"}, {"id": "f5", "type": "textarea", "label": "What I want to try next time"}]'::jsonb, array['OCD', 'mindfulness', 'intrusive thoughts']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('sensation-describing-practice', 'Sensation Describing Practice', 'dbt'::resource_kind, 'Has a client name body sensations during panic in plain, factual words without judging them.', 'Describe physical sensations accurately so they feel less alarming.', array['Adults']::text[], '20 minutes', 'Use it when the client reads sensations as danger. Practice in session with a neutral sensation first, then a stronger one. Keep the language factual, such as tight, warm, or fluttering. Note how the description shifts attention, and do not push the client into sensations they are not ready for.', '[{"id": "f0", "type": "textarea", "label": "The sensation I noticed and where it was"}, {"id": "f1", "type": "textarea", "label": "Factual words for it, such as warm or tight"}, {"id": "f2", "type": "textarea", "label": "The story my mind added to it"}, {"id": "f3", "type": "textarea", "label": "How strong it was from 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What I did to let it be there for a minute"}, {"id": "f5", "type": "textarea", "label": "What changed as I kept describing it"}, {"id": "f6", "type": "textarea", "label": "What I want to practice this week"}]'::jsonb, array['panic attacks', 'mindfulness', 'observe and describe']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('night-shift-request-script', 'Night Shift Request Script', 'dbt'::resource_kind, 'Helps a new parent ask a partner or helper for specific support with nights and sleep.', 'Turn an exhausted wish for help into one clear, doable request.', array['Adults']::text[], '20 minutes', 'New parents often hint and hope instead of asking. Have the client write the request in plain words and say it aloud. Keep it concrete, such as one block of protected sleep. Note any feelings of guilt that come up, and use your judgment about further support.', '[{"id": "f0", "type": "textarea", "label": "What I most need help with at night"}, {"id": "f1", "type": "textarea", "label": "Who I am asking"}, {"id": "f2", "type": "textarea", "label": "The facts of the situation in one sentence"}, {"id": "f3", "type": "textarea", "label": "How I feel about it, using I"}, {"id": "f4", "type": "textarea", "label": "My specific request, including when"}, {"id": "f5", "type": "textarea", "label": "What I can offer in return"}, {"id": "f6", "type": "textarea", "label": "What I will do if the answer is no"}]'::jsonb, array['perinatal and postpartum', 'DEAR MAN', 'sleep']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('proud-moments-mastery-log', 'Proud Moments Mastery Log', 'dbt'::resource_kind, 'Records small actions done well each day so a client can see evidence of capability.', 'Build a record of competence that counters a harsh self-view.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Ask for small, specific moments rather than big achievements. Clients with a harsh self-view often dismiss entries, so ask what they would say if a friend had done the same thing. Review the log together and read back a few entries aloud.', '[{"id": "f0", "type": "textarea", "label": "Something I did today that took effort"}, {"id": "f1", "type": "textarea", "label": "Why it counts, even if it was small"}, {"id": "f2", "type": "textarea", "label": "What strength or skill I used"}, {"id": "f3", "type": "textarea", "label": "How I felt in my body when I finished"}, {"id": "f4", "type": "textarea", "label": "What a close friend would say about it"}, {"id": "f5", "type": "textarea", "label": "One small thing I want to do tomorrow"}]'::jsonb, array['self-esteem', 'mastery', 'self-compassion']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('after-the-event-facts-review', 'After the Event Facts Review', 'dbt'::resource_kind, 'Helps a client look back on a social event and check the story their mind told about it.', 'Check the post-event story against what actually happened.', array['Adults', 'Teens']::text[], '20 minutes', 'Use it after a real social situation when the client is replaying it. Have them separate what happened from what they imagined others thought. The review works best when it includes neutral or good moments, which are often left out. Stop the review if it turns into more rumination.', '[{"id": "f0", "type": "textarea", "label": "What happened, in facts a camera could record"}, {"id": "f1", "type": "textarea", "label": "What my mind said about how it went"}, {"id": "f2", "type": "textarea", "label": "The facts that fit that story"}, {"id": "f3", "type": "textarea", "label": "The facts that do not fit it"}, {"id": "f4", "type": "textarea", "label": "A fairer way to describe the event"}, {"id": "f5", "type": "textarea", "label": "One thing that went okay"}, {"id": "f6", "type": "textarea", "label": "What I will do to let the event go"}]'::jsonb, array['social anxiety', 'check the facts', 'rumination']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('repair-after-conflict-sheet', 'Repair After Conflict Sheet', 'dbt'::resource_kind, 'Plans a calm, sincere repair after an argument, using DBT interpersonal skills.', 'Move from a painful conflict to a plan for repair that keeps self-respect.', array['Adults']::text[], '30 minutes', 'Work on this once the client has calmed down, not in the middle of distress. Clients often want to explain first; ask what the other person most needs to hear. Keep repair and self-respect both in the plan, and rehearse the opening line aloud.', '[{"id": "f0", "type": "textarea", "label": "What happened, in facts only"}, {"id": "f1", "type": "textarea", "label": "What I am willing to own in the conflict"}, {"id": "f2", "type": "textarea", "label": "What I am not willing to give up"}, {"id": "f3", "type": "textarea", "label": "What the other person may need to hear"}, {"id": "f4", "type": "textarea", "label": "My opening line for the repair"}, {"id": "f5", "type": "textarea", "label": "The skill I will use if it gets tense"}, {"id": "f6", "type": "textarea", "label": "When and where I will talk"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'repair']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('trusted-support-circle-map', 'Trusted Support Circle Map', 'dbt'::resource_kind, 'Maps who is safe and steady in a client''s life and what each person can offer.', 'Identify and strengthen safe sources of support at the client''s own pace.', array['Adults']::text[], '30 minutes', 'Let the client set the pace and leave out any details of what happened. Start with the people and places that feel even a little safe, and respect the decision to keep the circle small. Clients may find it hard to ask for help, so plan one small ask together and review it.', '[{"id": "f0", "type": "textarea", "label": "People who feel safe to be around"}, {"id": "f1", "type": "textarea", "label": "A place that feels calming"}, {"id": "f2", "type": "textarea", "label": "What each person can offer, such as listening or company"}, {"id": "f3", "type": "textarea", "label": "What I do not want to talk about, and how I can say so"}, {"id": "f4", "type": "textarea", "label": "One small request I could make this week"}, {"id": "f5", "type": "textarea", "label": "A way to reach someone when I feel unsteady"}, {"id": "f6", "type": "textarea", "label": "What helps me feel I have a choice in asking"}]'::jsonb, array['sexual abuse', 'support', 'safety']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('willingness-ladder-for-feared-situations', 'Willingness Ladder for Feared Situations', 'dbt'::resource_kind, 'Builds a stepwise ladder of feared situations with a willing stance toward each small step.', 'Pair small, chosen steps toward feared things with acceptance skills.', array['Adults']::text[], '30 minutes', 'Have the client rate each step and choose one they are willing to try, not one they think they should. Pair the step with a skill they will use during it. Keep the steps small and review after each one, since repeating a step is fine.', '[{"id": "f0", "type": "textarea", "label": "The feared situation I want to move toward"}, {"id": "f1", "type": "textarea", "label": "Five steps from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "My willingness for each step from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "The first step I will try and when"}, {"id": "f4", "type": "textarea", "label": "The skill I will use during it"}, {"id": "f5", "type": "textarea", "label": "What I expect to feel"}, {"id": "f6", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['phobias', 'willingness', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('body-appreciation-mindfulness-practice', 'Body Appreciation Mindfulness Practice', 'dbt'::resource_kind, 'Invites a client to notice what the body does and to meet hard moments with kindness.', 'Shift attention from looks to function and respond to hard moments with care.', array['Adults', 'Teens']::text[], '15 minutes', 'Keep the focus on what the body does, such as walking, hugging, or breathing, and avoid any talk about size or shape. Clients may find this awkward at first, so offer small, honest steps. Watch for discomfort and let the client skip items that feel forced.', '[{"id": "f0", "type": "textarea", "label": "Three things my body did for me today"}, {"id": "f1", "type": "textarea", "label": "A moment I felt at ease in my body"}, {"id": "f2", "type": "textarea", "label": "A critical thought that showed up and what I noticed about it"}, {"id": "f3", "type": "textarea", "label": "A kind sentence I could say to myself in that moment"}, {"id": "f4", "type": "textarea", "label": "One caring thing I can do for my body today"}, {"id": "f5", "type": "textarea", "label": "Who I can talk with when the thoughts get loud"}]'::jsonb, array['body image', 'mindfulness', 'self-compassion']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('weekend-reconnection-planner', 'Weekend Reconnection Planner', 'couples'::resource_kind, 'Two partners each plan one small shared activity and one solo recharge for the weekend.', 'Build a predictable pocket of connection without either partner feeling crowded.', array['Couples']::text[], '20 minutes', 'Have each partner fill in their own side first, then compare. Couples often plan too much, so cap it at one shared activity. Notice whether one partner''s recharge time reads as rejection to the other, and name that out loud before the weekend.', '[{"id": "f0", "type": "textarea", "label": "Partner A: one thing I would enjoy doing together this weekend"}, {"id": "f1", "type": "textarea", "label": "Partner B: one thing I would enjoy doing together this weekend"}, {"id": "f2", "type": "textarea", "label": "Partner A: how I like to recharge on my own"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I like to recharge on my own"}, {"id": "f4", "type": "textarea", "label": "Together: the one shared activity we chose and when"}, {"id": "f5", "type": "textarea", "label": "Together: how we will say so kindly if we need a change of plan"}]'::jsonb, array['connection', 'routines', 'communication']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('two-sides-of-one-story-retelling', 'Two Sides of One Story Retelling', 'couples'::resource_kind, 'Each partner retells a recent disagreement from the other partner''s point of view.', 'Build perspective-taking before problem-solving begins.', array['Couples']::text[], '30 minutes', 'Choose a low-intensity disagreement, not the biggest one. Partner A retells it as Partner B experienced it, then Partner B corrects gently and adds what was missed. Stop the exercise if either partner becomes flooded. The point is being understood, not agreeing on the facts.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the disagreement in one sentence"}, {"id": "f1", "type": "textarea", "label": "Partner A: how I think Partner B felt during it"}, {"id": "f2", "type": "textarea", "label": "Partner B: what Partner A got right about my side"}, {"id": "f3", "type": "textarea", "label": "Partner B: what Partner A missed about my side"}, {"id": "f4", "type": "textarea", "label": "Partner B: the disagreement in one sentence"}, {"id": "f5", "type": "textarea", "label": "Partner B: how I think Partner A felt during it"}, {"id": "f6", "type": "textarea", "label": "Partner A: what Partner B got right about my side"}, {"id": "f7", "type": "textarea", "label": "Together: one thing we each understand better now"}]'::jsonb, array['perspective-taking', 'communication', 'conflict']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('shared-calendar-expectations-talk', 'Shared Calendar Expectations Talk', 'couples'::resource_kind, 'Partners compare how each expects time, plans and commitments to be handled.', 'Surface mismatched expectations about time before they turn into resentment.', array['Couples']::text[], '25 minutes', 'Mismatched expectations about plans, lateness and last-minute changes often sit under recurring arguments. Ask each partner to write before speaking. Watch for one partner treating their own style as the standard, and help them frame differences as preferences rather than flaws.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I like plans to be made and shared"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I like plans to be made and shared"}, {"id": "f2", "type": "textarea", "label": "Partner A: what being late or changing plans means to me"}, {"id": "f3", "type": "textarea", "label": "Partner B: what being late or changing plans means to me"}, {"id": "f4", "type": "textarea", "label": "Together: one calendar habit we will try for two weeks"}, {"id": "f5", "type": "textarea", "label": "Together: how we will check whether it is working"}]'::jsonb, array['planning', 'expectations', 'communication']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('gratitude-letters-swap-for-couples', 'Gratitude Letters Swap for Couples', 'couples'::resource_kind, 'Partners write short notes naming specific things they value and read them aloud.', 'Give each partner specific, spoken appreciation they can keep.', array['Couples']::text[], '25 minutes', 'Ask for specifics, not general praise: an actual moment and what it showed about the partner. Some people deflect compliments, so coach the listener to simply say thank you. Listening without rebuttal is part of the exercise, and worth debriefing afterward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a moment this month when I felt grateful for you"}, {"id": "f1", "type": "textarea", "label": "Partner A: what that moment showed me about you"}, {"id": "f2", "type": "textarea", "label": "Partner B: a moment this month when I felt grateful for you"}, {"id": "f3", "type": "textarea", "label": "Partner B: what that moment showed me about you"}, {"id": "f4", "type": "textarea", "label": "Partner A: how it felt to hear Partner B''s note"}, {"id": "f5", "type": "textarea", "label": "Partner B: how it felt to hear Partner A''s note"}]'::jsonb, array['appreciation', 'gratitude', 'connection']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('decision-making-style-comparison', 'Decision-Making Style Comparison', 'couples'::resource_kind, 'Partners map how each prefers to make joint decisions and where the styles collide.', 'Reduce standoffs by making each partner''s decision style visible.', array['Couples']::text[], '30 minutes', 'Some people decide fast and revisit, others research before committing, and each can read the other as careless or stalling. Use a recent decision as the example. Help the couple agree on a shared process, such as a deadline plus one veto each, rather than picking a winner.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I usually like to make a big decision"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I usually like to make a big decision"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I find hard about Partner B''s style"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I find hard about Partner A''s style"}, {"id": "f4", "type": "textarea", "label": "Together: a recent decision where our styles collided"}, {"id": "f5", "type": "textarea", "label": "Together: a process for our next decision that respects both styles"}]'::jsonb, array['decision-making', 'communication', 'conflict']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('trauma-triggers-and-partner-grounding-card', 'Trauma Triggers and Partner Grounding Card', 'couples'::resource_kind, 'Partners record one person''s known reminders and the grounding help the other can offer.', 'Give the supporting partner a clear, agreed way to help during a hard moment.', array['Couples']::text[], '30 minutes', 'Keep this about present-day cues and support, never about retelling what happened. Let the partner who has the reminders lead and set the pace. The supporting partner''s job is to offer agreed grounding, not to question. Revisit the card regularly since what helps can change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a few reminders that can make things feel unsafe for me now"}, {"id": "f1", "type": "textarea", "label": "Partner A: signs in my body that I am getting overwhelmed"}, {"id": "f2", "type": "textarea", "label": "Partner A: what helps me feel grounded and what does not"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I will say and do when I notice those signs"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I will avoid doing"}, {"id": "f5", "type": "textarea", "label": "Together: the signal Partner A can give to ask for space or help"}, {"id": "f6", "type": "textarea", "label": "Together: who else we can turn to for support"}]'::jsonb, array['PTSD and trauma', 'grounding', 'support']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('low-energy-day-partner-menu', 'Low Energy Day Partner Menu', 'couples'::resource_kind, 'A menu where the partner with low mood picks the help they want and the other offers it.', 'Replace guessing and pressure with a simple menu of support on hard days.', array['Couples']::text[], '25 minutes', 'Pressure to cheer up and helpful fixing both tend to backfire on low days. A menu lets the partner with low mood choose without explaining. Coach the other partner to offer the item without debating it. Review together what worked, and adjust the menu as needs change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: things that feel like real help when my mood is low"}, {"id": "f1", "type": "textarea", "label": "Partner A: things that feel like pressure, even when well meant"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can offer on a hard day from Partner A''s list"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I can look after my own energy too"}, {"id": "f4", "type": "textarea", "label": "Together: a word or sign for picking something off the menu"}, {"id": "f5", "type": "textarea", "label": "Together: a small thing we can still do together on a low day"}]'::jsonb, array['depression', 'support', 'communication']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('shared-systems-design-session', 'Shared Systems Design Session', 'couples'::resource_kind, 'Partners design one shared routine together, with each person''s strengths named up front.', 'Build a household system around how both partners'' attention really works.', array['Couples']::text[], '35 minutes', 'Start with strengths, not failures, so the partner with attention difficulties is not cast as the problem. Choose one routine only, such as mornings or bills. Systems that live in view, like a whiteboard or shared alarm, tend to outlast reminders spoken by one partner to the other.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I am good at in our household"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I am good at in our household"}, {"id": "f2", "type": "textarea", "label": "Partner A: where I tend to lose track, without blame"}, {"id": "f3", "type": "textarea", "label": "Partner B: where I tend to lose track, without blame"}, {"id": "f4", "type": "textarea", "label": "Together: the one routine we want to make easier"}, {"id": "f5", "type": "textarea", "label": "Together: the visible reminder or system we will try"}, {"id": "f6", "type": "textarea", "label": "Together: when we will review it"}]'::jsonb, array['ADHD', 'routines', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('anger-repair-conversation-planner', 'Anger Repair Conversation Planner', 'couples'::resource_kind, 'Partners plan the conversation they will have after an angry moment has passed.', 'Turn cooled-down anger into repair rather than silence or blame.', array['Couples']::text[], '30 minutes', 'Use this only once both partners are calm, and stop if anyone escalates. The partner who got angry goes first, naming their part without a but. Then the other shares the impact. Check that the repair includes one concrete change, not just an apology.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I was feeling underneath the anger"}, {"id": "f1", "type": "textarea", "label": "Partner A: my part in how it went, with no but"}, {"id": "f2", "type": "textarea", "label": "Partner B: how it felt to be on the receiving end"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I needed in that moment"}, {"id": "f4", "type": "textarea", "label": "Partner A: one concrete thing I will do differently"}, {"id": "f5", "type": "textarea", "label": "Partner B: one thing I can do to help the next time"}, {"id": "f6", "type": "textarea", "label": "Together: how we will know we have repaired enough to move on"}]'::jsonb, array['anger management', 'repair', 'conflict']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('reassurance-pause-agreement-for-partners', 'Reassurance Pause Agreement for Partners', 'couples'::resource_kind, 'Partners agree on a gentler response than repeated reassurance when intrusive worries spike.', 'Replace repeated reassuring with a plan both partners can live with.', array['Couples']::text[], '30 minutes', 'Repeated reassurance can ease things briefly and keep worries going. Build the agreement together and avoid framing it as withdrawal of love. The supporting partner needs a warm line to say instead. Go slowly, and expect both partners to feel uncomfortable at first.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the worries that most often lead me to ask for reassurance"}, {"id": "f1", "type": "textarea", "label": "Partner A: how it feels in my body when I am waiting for an answer"}, {"id": "f2", "type": "textarea", "label": "Partner B: how it feels to be asked again and again"}, {"id": "f3", "type": "textarea", "label": "Partner B: a warm line I can say instead of answering the question"}, {"id": "f4", "type": "textarea", "label": "Together: what Partner A will try during the pause"}, {"id": "f5", "type": "textarea", "label": "Together: how we will check in afterward and what we will say to each other"}]'::jsonb, array['OCD', 'family accommodation', 'support']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('panic-night-plan-for-couples', 'Panic Night Plan for Couples', 'couples'::resource_kind, 'Partners write a simple plan for a panic episode that strikes at night.', 'Give both partners a script for the night so neither has to improvise.', array['Couples']::text[], '25 minutes', 'Night episodes leave the partner frightened and unsure. Write the plan when both are calm. Keep it short enough to follow half asleep. Ask the partner with panic what they want said, and the other partner what they need so they can stay steady. Rehearse it once in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I notice first when panic starts at night"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I want my partner to say to me"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I do not want my partner to do"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I will do in the first two minutes"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I will tell myself so I can stay calm"}, {"id": "f5", "type": "textarea", "label": "Together: what we do the next morning"}]'::jsonb, array['panic attacks', 'support', 'planning']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('postpartum-couple-reconnection-plan', 'Postpartum Couple Reconnection Plan', 'couples'::resource_kind, 'New parents each name what they miss and plan one small moment of connection.', 'Protect a few minutes of couple connection while the household is stretched thin.', array['Couples']::text[], '25 minutes', 'New parents are often tired and invisible to each other. Keep the plan very small, such as ten minutes after the baby sleeps. Let each partner say what they miss without it becoming a complaint. Encourage them to talk with their clinician or doctor if low mood or worry seems to be growing.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I miss about us right now"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I miss about us right now"}, {"id": "f2", "type": "textarea", "label": "Partner A: one small moment that would help me feel close"}, {"id": "f3", "type": "textarea", "label": "Partner B: one small moment that would help me feel close"}, {"id": "f4", "type": "textarea", "label": "Together: when we will try it this week"}, {"id": "f5", "type": "textarea", "label": "Together: what we will do if it does not happen"}]'::jsonb, array['perinatal and postpartum', 'connection', 'relationship issues']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('inner-critic-kindness-exchange', 'Inner Critic Kindness Exchange', 'couples'::resource_kind, 'Each partner shares one harsh self-judgment and hears how the other sees them.', 'Let partners offer each other a kinder, more accurate view than the inner critic''s.', array['Couples']::text[], '25 minutes', 'Ask the speaker to name the critic''s words in the third person to soften the pull. The listener reflects what they see in their partner, without arguing or flooding with praise. Watch for compliments that are rejected, and invite the speaker to simply notice how it lands.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something my inner critic says about me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I see in Partner A that the critic leaves out"}, {"id": "f2", "type": "textarea", "label": "Partner B: something my inner critic says about me"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I see in Partner B that the critic leaves out"}, {"id": "f4", "type": "textarea", "label": "Partner A: how it felt to hear that"}, {"id": "f5", "type": "textarea", "label": "Partner B: how it felt to hear that"}, {"id": "f6", "type": "textarea", "label": "Together: a phrase we can use when the critic gets loud"}]'::jsonb, array['self-esteem', 'support', 'communication']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('grief-anniversaries-plan-for-couples', 'Grief Anniversaries Plan for Couples', 'couples'::resource_kind, 'Partners plan how to spend a hard date, with each person''s wishes named.', 'Prepare for a painful date so neither partner is surprised by the other''s needs.', array['Couples']::text[], '25 minutes', 'Partners can grieve differently, one wanting company and the other quiet. Plan ahead for a birthday, anniversary or holiday. Make space for both needs, and build in a fallback if the day goes differently. Leave room for unplanned feelings and for asking others to share the day.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I would like this day to look like"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I would like this day to look like"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I hope my partner will do or say"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I hope my partner will do or say"}, {"id": "f4", "type": "textarea", "label": "Together: how we will honor the person or loss"}, {"id": "f5", "type": "textarea", "label": "Together: what we will do if one of us needs to change the plan"}, {"id": "f6", "type": "textarea", "label": "Together: who else we want with us, if anyone"}]'::jsonb, array['grief and loss', 'rituals', 'support']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('weekly-relationship-rating-review', 'Weekly Relationship Rating Review', 'couples'::resource_kind, 'Partners privately rate several areas of the relationship, then compare and choose one focus.', 'Give both partners a simple shared picture of what is working and what needs attention.', array['Couples']::text[], '30 minutes', 'Rate privately before sharing to avoid anchoring on the first partner''s answers. Differences in ratings are useful information, not a contest. Help the couple choose one area only for the coming week and agree on one small action each.', '[{"id": "f0", "type": "textarea", "label": "Partner A: areas that feel good right now"}, {"id": "f1", "type": "textarea", "label": "Partner A: areas that need attention"}, {"id": "f2", "type": "textarea", "label": "Partner B: areas that feel good right now"}, {"id": "f3", "type": "textarea", "label": "Partner B: areas that need attention"}, {"id": "f4", "type": "textarea", "label": "Together: the one area we will focus on this week"}, {"id": "f5", "type": "textarea", "label": "Partner A: my small action"}, {"id": "f6", "type": "textarea", "label": "Partner B: my small action"}]'::jsonb, array['relationship issues', 'connection', 'goal setting']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('paced-closeness-conversation-guide', 'Paced Closeness Conversation Guide', 'couples'::resource_kind, 'Partners talk about touch, closeness and pacing, with one partner''s choices leading.', 'Support a survivor''s sense of choice and safety while keeping partners connected.', array['Couples']::text[], '30 minutes', 'Use only with the survivor''s consent and pacing, and never ask for details of the past. The survivor sets the agenda, including yes, no and later. The other partner practices hearing no without hurt or pressure. Consider whether individual support alongside the couple work would help.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what feels safe and comforting right now"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I would like to go slowly with or not do"}, {"id": "f2", "type": "textarea", "label": "Partner A: a signal I can use to say stop or pause"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will respond when I hear no or later"}, {"id": "f4", "type": "textarea", "label": "Partner B: other ways I can show closeness that feel safe"}, {"id": "f5", "type": "textarea", "label": "Together: a check-in question we will use before being close"}, {"id": "f6", "type": "textarea", "label": "Together: who supports each of us outside the relationship"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('fear-facing-teamwork-plan', 'Fear Facing Teamwork Plan', 'couples'::resource_kind, 'Partners agree how the supporter can cheer on each small step a partner takes toward a fear.', 'Keep the supporting partner encouraging without pushing, rescuing or avoiding.', array['Couples']::text[], '25 minutes', 'Support can slide into rescuing or rushing. Agree on the supporter''s role before a practice begins. The partner facing the fear chooses the step and the pace. Ask the supporter to notice effort, not outcome, and plan how they both respond if the step is stopped early.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the fear I am working on and my next small step"}, {"id": "f1", "type": "textarea", "label": "Partner A: what kind of encouragement helps me"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I do not want my partner to do"}, {"id": "f3", "type": "textarea", "label": "Partner B: how I will cheer on the step without pushing"}, {"id": "f4", "type": "textarea", "label": "Partner B: how I will respond if Partner A stops early"}, {"id": "f5", "type": "textarea", "label": "Together: how we will celebrate the effort afterward"}]'::jsonb, array['phobias', 'support', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('self-talk-and-partner-words-exchange', 'Self-Talk and Partner Words Exchange', 'couples'::resource_kind, 'Partners share how they talk about their own appearance and agree on supportive language.', 'Help couples build language that supports each person''s feelings about their body.', array['Couples']::text[], '25 minutes', 'Focus on words and feelings, never on any measurement or rule. Ask each partner how they speak about themselves in front of the other, and how the other''s words land. Agree on phrases that feel kind and on topics each partner prefers to leave alone.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I tend to talk about my appearance out loud"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I tend to talk about my appearance out loud"}, {"id": "f2", "type": "textarea", "label": "Partner A: words from my partner that feel kind to me"}, {"id": "f3", "type": "textarea", "label": "Partner B: words from my partner that feel kind to me"}, {"id": "f4", "type": "textarea", "label": "Partner A: topics I would rather we not discuss"}, {"id": "f5", "type": "textarea", "label": "Partner B: topics I would rather we not discuss"}, {"id": "f6", "type": "textarea", "label": "Together: a phrase we will use when one of us is being hard on ourselves"}]'::jsonb, array['body image', 'communication', 'support']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('mood-garden-drawing', 'Mood Garden Drawing', 'kids'::resource_kind, 'The child draws a garden where each plant stands for a feeling and the weather around it.', 'Give a child a picture language for moods they cannot yet name aloud.', array['Children']::text[], '25 minutes', 'Hand over paper and crayons and let the child pick which feelings get a plant, then ask what each one needs to grow or rest. Keep your questions curious and let the drawing lead. Invite the parent for the last five minutes to hear the garden tour and to water one plant at home with a kind word this week.', '[{"id": "f0", "type": "textarea", "label": "The plants in my garden and the feeling each one is"}, {"id": "f1", "type": "textarea", "label": "What the weather is like in my garden today"}, {"id": "f2", "type": "textarea", "label": "The plant that is hardest to look after"}, {"id": "f3", "type": "textarea", "label": "What that plant needs from me"}, {"id": "f4", "type": "textarea", "label": "Who helps me in my garden"}]'::jsonb, array['emotion identification', 'children', 'art']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('pillow-fort-calm-corner-build', 'Pillow Fort Calm Corner Build', 'kids'::resource_kind, 'The child and parent build a small cozy corner at home and stock it with calming items.', 'Create a reliable physical spot where a child can settle before a big feeling grows.', array['Children']::text[], 'Full session', 'Build a mini version in the office with cushions and a blanket, then plan the home version together. The parent''s job is to stay nearby and never use the corner as a punishment. Watch for a child who wants it only as a hiding place and talk through when it helps and when a grown-up check-in helps more.', '[{"id": "f0", "type": "textarea", "label": "What my calm corner looks like"}, {"id": "f1", "type": "textarea", "label": "Three things I want inside it"}, {"id": "f2", "type": "textarea", "label": "What I do there to feel better"}, {"id": "f3", "type": "textarea", "label": "How I will tell a grown-up I need it"}, {"id": "f4", "type": "textarea", "label": "What my parent does when I am in it"}]'::jsonb, array['self-soothing', 'children', 'parenting', 'coping skills']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('friendship-recipe-card-game', 'Friendship Recipe Card Game', 'kids'::resource_kind, 'Players draw ingredient cards and build a silly recipe for being a good friend.', 'Practice the small moves of friendship through play and a shared debrief.', array['Children', 'Teens']::text[], '30 minutes', 'Each player takes a turn drawing a card such as sharing, listening or saying sorry, acting it out, and adding it to the recipe bowl. The group votes on which ingredient was hardest to do. Debrief on one ingredient each child will try this week. Keep the tone light so a shy child can pass once without losing face.', '[{"id": "f0", "type": "textarea", "label": "An ingredient I am already good at"}, {"id": "f1", "type": "textarea", "label": "An ingredient that feels tricky"}, {"id": "f2", "type": "textarea", "label": "A time a friend used one with me"}, {"id": "f3", "type": "textarea", "label": "How it felt when they did"}, {"id": "f4", "type": "textarea", "label": "The one I will try this week"}]'::jsonb, array['friendship', 'children', 'play', 'social skills']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('bedtime-worry-letterbox', 'Bedtime Worry Letterbox', 'kids'::resource_kind, 'The child decorates a box and posts worries on paper before bed so the night can be quiet.', 'Give a child a simple ritual to hand worries off before sleep.', array['Children']::text[], '25 minutes', 'Decorate a shoebox as a letterbox together and practice drawing or dictating a worry and posting it. The parent reads nothing at night and opens the box at a set morning time with the child. Explain that the box holds worries without solving them. If a child names fear for their safety, follow your usual duty to report and share the concern with the caregiver.', '[{"id": "f0", "type": "textarea", "label": "What my letterbox looks like"}, {"id": "f1", "type": "textarea", "label": "A worry I can post tonight"}, {"id": "f2", "type": "textarea", "label": "Who I tell if a worry will not stay in the box"}, {"id": "f3", "type": "textarea", "label": "A cozy thought to think after posting"}, {"id": "f4", "type": "textarea", "label": "What my parent and I do in the morning"}]'::jsonb, array['sleep', 'worry', 'children', 'routines']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('kindness-chain-paper-craft', 'Kindness Chain Paper Craft', 'kids'::resource_kind, 'Each link holds a kind act the child did or saw, and the chain grows across the week.', 'Help a child notice and collect moments of kindness in daily life.', array['Children']::text[], 'One week', 'Cut paper strips and start the first link in session, then send the chain home. The parent writes or draws what the child reports on each link without adding commentary or rewards. Review the chain the next visit and ask which link felt best to make. Children who find it hard to think of a link can use kindness they received.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did this week"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "How my body felt after"}, {"id": "f3", "type": "textarea", "label": "A link I want to add next"}, {"id": "f4", "type": "textarea", "label": "Who I want to show the chain to"}]'::jsonb, array['kindness', 'children', 'art']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('worry-weather-forecast-board', 'Worry Weather Forecast Board', 'kids'::resource_kind, 'The child draws a forecast for the day''s worries and plans a small umbrella for each.', 'Help a child predict, name and plan for worry instead of being caught off guard.', array['Children']::text[], '25 minutes', 'Use a large sheet as a weather map and let the child place sun, cloud and storm symbols for situations ahead. Pair each cloud with one small coping choice. The parent learns to ask about the forecast at breakfast instead of reassuring repeatedly. If reassurance seeking comes up, plan together how the parent can respond warmly and briefly.', '[{"id": "f0", "type": "textarea", "label": "Today''s forecast for my worries"}, {"id": "f1", "type": "textarea", "label": "The stormiest part of my week"}, {"id": "f2", "type": "textarea", "label": "My umbrella for that storm"}, {"id": "f3", "type": "textarea", "label": "A sunny thing to look forward to"}, {"id": "f4", "type": "textarea", "label": "Who I can tell when the clouds get big"}]'::jsonb, array['anxiety', 'children', 'worry', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('gray-cloud-and-sunshine-sticker-map', 'Gray Cloud and Sunshine Sticker Map', 'kids'::resource_kind, 'The child maps a day into gray cloud and sunshine moments with stickers and drawing.', 'Let a child show how low mood moves through a day and where small lifts exist.', array['Children']::text[], '25 minutes', 'Draw a simple day line and place stickers for gray cloud and sunny times. Be curious about the sunny ones, however small, and wonder aloud what was different. The parent adds one planned sunny moment to the week and joins in without expecting cheerfulness. If a child talks about not wanting to be here, stay with them and ask about 988 (call or text) with the caregiver in session.', '[{"id": "f0", "type": "textarea", "label": "A gray cloud moment from today"}, {"id": "f1", "type": "textarea", "label": "A sunny moment, even a tiny one"}, {"id": "f2", "type": "textarea", "label": "What I was doing in the sunny moment"}, {"id": "f3", "type": "textarea", "label": "One sunny thing I could add this week"}, {"id": "f4", "type": "textarea", "label": "Who I want with me on gray days"}]'::jsonb, array['depression', 'children', 'mood', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('get-ready-race-track-chart', 'Get-Ready Race Track Chart', 'kids'::resource_kind, 'A drawn race track turns the morning or homework routine into laps with stopping points.', 'Break a hard routine into visible steps so a child with busy attention can follow along.', array['Children']::text[], '25 minutes', 'Draw a track with a start, four to six pit stops and a finish, and let the child name each stop and decorate their car. Keep the steps short and the parent''s job to point at the track rather than repeat instructions. Try it for one routine only and review what got stuck. Adjust stops together rather than adding more.', '[{"id": "f0", "type": "textarea", "label": "The routine I want to race through"}, {"id": "f1", "type": "textarea", "label": "My pit stops in order"}, {"id": "f2", "type": "textarea", "label": "The pit stop where I get stuck"}, {"id": "f3", "type": "textarea", "label": "What helps me get going again"}, {"id": "f4", "type": "textarea", "label": "How my parent can cheer me on quietly"}]'::jsonb, array['ADHD', 'routines', 'children', 'parenting']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('cool-off-comic-strip', 'Cool-Off Comic Strip', 'kids'::resource_kind, 'The child draws a three-panel comic of a blowup, a pause and a better ending.', 'Help a child rehearse a pause between a mad feeling and what they do with it.', array['Children', 'Teens']::text[], '25 minutes', 'Let the child draw a recent frustrating moment in panel one, the pause in panel two and the new ending in panel three, with stick figures welcomed. Praise the pause, not the drawing. The parent reads the comic with the child and agrees on one cue word for the pause. Practice the pause in session with a calm voice model from you.', '[{"id": "f0", "type": "textarea", "label": "What happened in the first panel"}, {"id": "f1", "type": "textarea", "label": "What my body felt like"}, {"id": "f2", "type": "textarea", "label": "What I can do in the pause panel"}, {"id": "f3", "type": "textarea", "label": "How the ending turns out"}, {"id": "f4", "type": "textarea", "label": "The cue word my parent and I will use"}]'::jsonb, array['anger management', 'children', 'regulation', 'art']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('doubt-bully-comic-strip', 'Doubt Bully Comic Strip', 'kids'::resource_kind, 'The child draws the doubting voice as a character and writes a comeback in a speech bubble.', 'Help a child see intrusive doubts as a pushy voice they can talk back to.', array['Children', 'Teens']::text[], '30 minutes', 'Ask the child to draw the doubting voice as a silly character and give it a name, then fill a speech bubble with what it says and another with a bold comeback. The parent learns to say something like that sounds like the doubter instead of answering the question. Watch for rituals hiding inside the comic and keep the focus on not obeying the voice.', '[{"id": "f0", "type": "textarea", "label": "What my doubting character looks like and its name"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do"}, {"id": "f2", "type": "textarea", "label": "What it says when I do not listen"}, {"id": "f3", "type": "textarea", "label": "My comeback in a speech bubble"}, {"id": "f4", "type": "textarea", "label": "How my parent can help me talk back"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('family-team-huddle-board', 'Family Team Huddle Board', 'kids'::resource_kind, 'The family draws a team board with roles, a weekly huddle and a cheer that fits them.', 'Give parents a steady weekly rhythm for connection and small shared decisions.', array['Children']::text[], 'Full session', 'Invite the parent and child to decorate a team board together and choose a short weekly huddle time. The parent speaks first about something they noticed going well, then the child. Keep problems for later in the huddle and keep the huddle under ten minutes. Notice who talks most and gently even the turns out.', '[{"id": "f0", "type": "textarea", "label": "Our team name and cheer"}, {"id": "f1", "type": "textarea", "label": "One thing I noticed going well this week"}, {"id": "f2", "type": "textarea", "label": "Something I would like more of"}, {"id": "f3", "type": "textarea", "label": "How we will pick our huddle time"}, {"id": "f4", "type": "textarea", "label": "What we do when the huddle gets tense"}]'::jsonb, array['parenting', 'family', 'connection', 'children']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('new-baby-family-picture-book', 'New Baby Family Picture Book', 'kids'::resource_kind, 'The child draws pages about becoming a big sibling and what stays the same.', 'Help a child adjust to a new baby while the parent recovers and adapts.', array['Children']::text[], 'Two short sessions', 'Fold paper into a little book and draw pages such as what is changing, what stays the same and what the baby cannot do yet. The parent joins to add one thing they love about the child and one special moment just for them. Listen for a parent who sounds exhausted or low and follow up with them privately and gently.', '[{"id": "f0", "type": "textarea", "label": "What is different since the baby came"}, {"id": "f1", "type": "textarea", "label": "What is still exactly the same"}, {"id": "f2", "type": "textarea", "label": "A job I can do as a big sibling"}, {"id": "f3", "type": "textarea", "label": "A special time I want with my parent"}, {"id": "f4", "type": "textarea", "label": "What I do when I feel left out"}]'::jsonb, array['perinatal and postpartum', 'children', 'family', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('me-medal-making-craft', 'Me Medal Making Craft', 'kids'::resource_kind, 'The child designs and decorates medals that name real things they do well.', 'Build a child''s sense of worth through specific, honest strengths.', array['Children']::text[], '25 minutes', 'Cut medals from cardboard and let the child name each one for something real, like helping a friend or trying again. Avoid inflated praise and ask how they know it is true. The parent adds one medal of their own for the child and hangs the set at home. If the child struggles, offer a medal for effort or kindness.', '[{"id": "f0", "type": "textarea", "label": "A medal for something I do well"}, {"id": "f1", "type": "textarea", "label": "A medal for something I tried even though it was hard"}, {"id": "f2", "type": "textarea", "label": "A medal a friend would give me"}, {"id": "f3", "type": "textarea", "label": "A medal my parent would give me"}, {"id": "f4", "type": "textarea", "label": "Where I will hang my medals"}]'::jsonb, array['self-esteem', 'children', 'strengths', 'art']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('goodbye-balloon-letter-craft', 'Goodbye Balloon Letter Craft', 'kids'::resource_kind, 'The child draws or dictates a message to someone they miss and decorates a balloon to hold it.', 'Give a grieving child a gentle way to say what they want to say to someone they lost.', array['Children']::text[], '30 minutes', 'Offer paper, markers and a balloon outline, and let the child lead what goes in the message. Sit close and let silence be fine. The parent chooses a safe moment at home to let the balloon go or keep it and is told that grief arrives in waves. Go at the child''s pace and stop if the feeling is too big.', '[{"id": "f0", "type": "textarea", "label": "Who the balloon is for"}, {"id": "f1", "type": "textarea", "label": "What I want them to know"}, {"id": "f2", "type": "textarea", "label": "A favorite memory I have of them"}, {"id": "f3", "type": "textarea", "label": "What I miss the most"}, {"id": "f4", "type": "textarea", "label": "What I do when I feel sad about it"}]'::jsonb, array['grief and loss', 'children', 'memory', 'art']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('sharing-feelings-bridge-drawing', 'Sharing Feelings Bridge Drawing', 'kids'::resource_kind, 'Two people build a bridge drawing, each adding a plank with a feeling and a need.', 'Help a child and another family member say feelings and needs across a gap.', array['Children']::text[], '30 minutes', 'Draw a river with two banks and let the child and a parent take turns adding planks that say a feeling and a need. Each person listens without fixing. The debrief asks what it was like to hear the other person. Keep turns equal and keep the bridge simple so a child who is worried about conflict stays comfortable.', '[{"id": "f0", "type": "textarea", "label": "A feeling I want to share with you"}, {"id": "f1", "type": "textarea", "label": "What I need when I feel that"}, {"id": "f2", "type": "textarea", "label": "What I heard you say"}, {"id": "f3", "type": "textarea", "label": "A plank I want to add to our bridge"}, {"id": "f4", "type": "textarea", "label": "What makes it easier to talk with you"}]'::jsonb, array['relationship issues', 'children', 'family', 'communication']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('feelings-tool-wheel-spinner', 'Feelings Tool Wheel Spinner', 'kids'::resource_kind, 'The child builds a spinner of calming choices and spins for a tool to try together.', 'Give a child a fun, varied menu of ways to cope with big feelings.', array['Children']::text[], '30 minutes', 'Cut a paper wheel with six slices and let the child fill each with a drawn choice, like squeeze a pillow or draw scribbles. Spin and practice the tool right away. The parent can spin with the child during hard moments instead of offering advice. Retire tools that are not working rather than adding pressure.', '[{"id": "f0", "type": "textarea", "label": "Six tools for my wheel"}, {"id": "f1", "type": "textarea", "label": "The one I like best"}, {"id": "f2", "type": "textarea", "label": "The one that feels silly but works"}, {"id": "f3", "type": "textarea", "label": "A time I could use my wheel"}, {"id": "f4", "type": "textarea", "label": "How my parent can help me spin"}]'::jsonb, array['coping skills', 'children', 'regulation', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('fear-mountain-climbing-poster', 'Fear Mountain Climbing Poster', 'kids'::resource_kind, 'The child draws a mountain of feared steps and places a flag at each brave climb.', 'Plan small, repeatable steps toward a fear the child wants to face.', array['Children']::text[], '30 minutes', 'Draw a mountain and let the child pick a fear, then order small steps from base camp to summit, with a flag after each. Go slowly and let the child choose the next step. The parent practices staying calm and not rescuing, and cheers the effort rather than the lack of fear. Stop climbing if the step is too big and shrink it.', '[{"id": "f0", "type": "textarea", "label": "The fear I want to climb"}, {"id": "f1", "type": "textarea", "label": "Base camp, my easiest step"}, {"id": "f2", "type": "textarea", "label": "The steps up the mountain"}, {"id": "f3", "type": "textarea", "label": "The flag I plant after each step"}, {"id": "f4", "type": "textarea", "label": "How my parent helps me climb"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('bodies-are-amazing-adventure-map', 'Bodies Are Amazing Adventure Map', 'kids'::resource_kind, 'The child draws a map of what their body can do on a day''s adventures.', 'Help a child appreciate what their body does and feels without comparing it to others.', array['Children']::text[], '25 minutes', 'Draw an outline and let the child mark places like legs for running or hands for making art, then draw a route through a pretend day. Keep the talk about what bodies do and never about how they look. The parent says thanks to the body for one thing daily and models kind talk. Redirect comparisons to function and fun.', '[{"id": "f0", "type": "textarea", "label": "What my body did today"}, {"id": "f1", "type": "textarea", "label": "A place on my map I am thankful for"}, {"id": "f2", "type": "textarea", "label": "What my body likes to do most"}, {"id": "f3", "type": "textarea", "label": "What my body needs to feel good"}, {"id": "f4", "type": "textarea", "label": "A kind thing I can say to my body"}]'::jsonb, array['body image', 'children', 'play', 'art']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('strength-trading-post', 'Strength Trading Post', 'game'::resource_kind, 'Players swap strength cards and explain why they would trade or keep each one.', 'Help clients name strengths they use and strengths they want to build.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Deal each player five strength cards and let them trade one at a time, saying why. Turns go clockwise, and anyone may pass once. Debrief on which card was hardest to give away and which one someone else saw in them. Watch for clients who discount strengths they hold, and gently ask for one example.', '[{"id": "f0", "type": "textarea", "label": "The strength I kept and a time I used it"}, {"id": "f1", "type": "textarea", "label": "The strength I traded away and why"}, {"id": "f2", "type": "textarea", "label": "A strength someone saw in me today"}, {"id": "f3", "type": "textarea", "label": "One strength I want to use this week"}]'::jsonb, array['strengths', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('pause-button-pass', 'Pause Button Pass', 'game'::resource_kind, 'Players pass a ball and take one slow breath and one reset action on each catch.', 'Practice pausing before reacting, in a setting with low stakes.', array['Teens', 'Groups']::text[], '20 minutes', 'Players stand or sit in a circle and pass a soft ball. The catcher names one thing that bugs them, takes a slow breath, then picks a reset action before passing on. Speed up the pace each round so the pause gets harder. Debrief on when the pause felt easy and when it slipped, and how that maps onto real life.', '[{"id": "f0", "type": "textarea", "label": "What I named as my annoyance"}, {"id": "f1", "type": "textarea", "label": "The reset action I picked"}, {"id": "f2", "type": "textarea", "label": "When the pause got hard in the game"}, {"id": "f3", "type": "textarea", "label": "Where I could use a pause this week"}]'::jsonb, array['regulation', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('mood-forecast-charades', 'Mood Forecast Charades', 'game'::resource_kind, 'Players act out a mood level while others guess the number on a one to ten scale.', 'Build a shared language for mood intensity that clients can use between sessions.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Each player draws a card with a mood and a number from one to ten, then acts it without words. The group guesses both. Score nothing; the point is noticing how differently people show the same number. Debrief on which numbers were hard to read and how the client might signal their own number to people at home.', '[{"id": "f0", "type": "textarea", "label": "A mood and number I acted out"}, {"id": "f1", "type": "textarea", "label": "A number that was hard to read in someone else"}, {"id": "f2", "type": "textarea", "label": "How people close to me can tell my number"}, {"id": "f3", "type": "textarea", "label": "A signal I could use to share my number"}]'::jsonb, array['mood', 'emotion recognition', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('session-skill-scavenger-hunt', 'Session Skill Scavenger Hunt', 'game'::resource_kind, 'Clients search the room for objects that stand for skills they already use.', 'Help clients see the skills they already have and connect them to daily life.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Set a five-minute timer and have each client collect objects that stand for a skill, such as a pen for writing things out. Take turns showing one object and explaining the skill. Others may add a time they saw that skill used. In the debrief, ask which skill deserves a spot in the client''s week, and leave room for clients who feel they have none.', '[{"id": "f0", "type": "textarea", "label": "Objects I picked and the skill each stands for"}, {"id": "f1", "type": "textarea", "label": "A skill someone else pointed out in me"}, {"id": "f2", "type": "textarea", "label": "The skill I most want to use more"}, {"id": "f3", "type": "textarea", "label": "When I will use it this week"}]'::jsonb, array['skills', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('goal-relay-board-game', 'Goal Relay Board Game', 'game'::resource_kind, 'Players move a token across a board, answering goal-setting prompts on each space.', 'Turn a vague goal into a small first step the client can take this week.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Draw a simple path of ten spaces, each with a prompt such as what would be different, who could help, or what could get in the way. Players roll, move, and answer. The finish space asks for one small step with a day and time. Debrief on which prompt was hardest and help the client shrink the step until it feels doable.', '[{"id": "f0", "type": "textarea", "label": "The goal I played for"}, {"id": "f1", "type": "textarea", "label": "A roadblock that came up on the board"}, {"id": "f2", "type": "textarea", "label": "Who could help me"}, {"id": "f3", "type": "textarea", "label": "My first small step, with a day and time"}]'::jsonb, array['goals', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('worry-time-zone-hopscotch', 'Worry Time Zone Hopscotch', 'game'::resource_kind, 'Players hop through chalk zones sorting worries into act now, plan later and let go.', 'Help clients sort worries by what they can do, and when.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Mark three zones on the floor and give each player a stack of worry cards, written or drawn by them. Players read one, hop to the zone that fits, and say why. Others may ask one question but not argue. The zone for plan later gets a time on the clock. Debrief on worries that refused to fit, and what the body felt like in each zone.', '[{"id": "f0", "type": "textarea", "label": "A worry I put in act now, and the step"}, {"id": "f1", "type": "textarea", "label": "A worry I put in plan later, and when"}, {"id": "f2", "type": "textarea", "label": "A worry I tried to let go of"}, {"id": "f3", "type": "textarea", "label": "What my body felt like at each zone"}]'::jsonb, array['anxiety', 'worry', 'play', 'group']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('energy-bank-board-game', 'Energy Bank Board Game', 'game'::resource_kind, 'Players earn and spend energy tokens on daily activities as they move around a board.', 'Show how small pleasant or useful actions can refill low energy.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Give each player ten energy tokens. Spaces mark activities, some that cost tokens and some that refill them. Players choose which to land on when they roll a choice space and explain why. Debrief on which refills surprised them and which costs they could trim. Keep the tone light, and notice clients who feel too drained to play.', '[{"id": "f0", "type": "textarea", "label": "An activity that cost me energy"}, {"id": "f1", "type": "textarea", "label": "An activity that refilled me"}, {"id": "f2", "type": "textarea", "label": "One refill I could try this week"}, {"id": "f3", "type": "textarea", "label": "Who could help when my tokens run low"}]'::jsonb, array['depression', 'behavioral activation', 'play', 'group']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('urge-surfing-obstacle-course', 'Urge Surfing Obstacle Course', 'game'::resource_kind, 'Players move through an obstacle course while a timer runs, riding out an urge card at each station.', 'Practice waiting out urges with skills, one station at a time.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Set up four stations with cards naming a common urge and a skill to try, such as slow breathing, a cold drink, calling someone or a short walk. Players draw a card, name the urge, use the skill and time it. Debrief on how the urge changed over the minutes, and which skills they would try in real life. Substance use is never glamorized or shamed here.', '[{"id": "f0", "type": "textarea", "label": "An urge I faced at a station"}, {"id": "f1", "type": "textarea", "label": "The skill I used and how long I waited"}, {"id": "f2", "type": "textarea", "label": "How the urge changed while I waited"}, {"id": "f3", "type": "textarea", "label": "A skill I would try at home"}, {"id": "f4", "type": "textarea", "label": "Someone I could call when an urge is strong"}]'::jsonb, array['addiction', 'urges', 'distress tolerance', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('temperature-check-toss', 'Temperature Check Toss', 'game'::resource_kind, 'Players toss a beanbag onto a thermometer floor mat and describe anger at that level.', 'Help clients notice early anger signs before they reach the top of the scale.', array['Teens', 'Groups']::text[], '25 minutes', 'Mark a floor thermometer from calm to boiling. Players toss a beanbag, then describe what their body, thoughts and actions look like at that level, and one thing they could do. Others add ideas but give no advice unless asked. Debrief on which level is the best time to step in, and what gets in the way of stepping in.', '[{"id": "f0", "type": "textarea", "label": "Where my anger usually starts on the thermometer"}, {"id": "f1", "type": "textarea", "label": "My body signs at that level"}, {"id": "f2", "type": "textarea", "label": "What I could do at that level"}, {"id": "f3", "type": "textarea", "label": "What gets in the way of doing it"}]'::jsonb, array['anger management', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('the-doubt-dice-challenge', 'The Doubt Dice Challenge', 'game'::resource_kind, 'Players roll dice to set how long they wait before answering a doubt card.', 'Practice sitting with doubt without doing the usual checking or asking for reassurance.', array['Adults', 'Teens']::text[], '25 minutes', 'Each card holds a doubt that clients write for themselves, rated for how hard it feels. Roll a die to set the waiting time in minutes before any checking or reassurance. Play alongside them, taking turns. Keep cards in the client''s own words and leave exposure pacing to your judgment. Debrief on how the doubt felt at minute one versus the end.', '[{"id": "f0", "type": "textarea", "label": "A doubt I put on a card and how hard it feels"}, {"id": "f1", "type": "textarea", "label": "What I wanted to do while I waited"}, {"id": "f2", "type": "textarea", "label": "What happened to the doubt over time"}, {"id": "f3", "type": "textarea", "label": "How long I want to wait next time"}]'::jsonb, array['OCD', 'uncertainty', 'exposure', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('parent-teacher-role-swap-game', 'Parent Teacher Role Swap Game', 'game'::resource_kind, 'Parent and child swap roles and act out everyday moments with turns and a debrief.', 'Help parents see everyday moments through their child''s eyes and practice a calmer response.', array['Children', 'Adults']::text[], '30 minutes', 'Choose three everyday scenes, such as bedtime or leaving the park. Parent and child swap roles, act the scene for one minute, then switch back. Keep it silly and safe. Ask what felt fair, and what the child wished the grown-up would say. If a child discloses anything worrying in play, follow your reporting duties. Parents choose one phrase to try this week.', '[{"id": "f0", "type": "textarea", "label": "The scene we acted out"}, {"id": "f1", "type": "textarea", "label": "What it felt like to be my child"}, {"id": "f2", "type": "textarea", "label": "What I wish my grown-up would say"}, {"id": "f3", "type": "textarea", "label": "One new phrase I will try this week"}]'::jsonb, array['parenting', 'play', 'family']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('sleepy-day-support-bingo', 'Sleepy Day Support Bingo', 'game'::resource_kind, 'Players mark a bingo card of small supports they could ask for or accept.', 'Help new parents name the help they need and practice asking for it.', array['Adults']::text[], '25 minutes', 'Fill the card with supports such as a meal, an hour of sleep, a walk or a listening ear. Play one-on-one or in a group. When a square is marked, say who could give it and how to ask. Debrief on which square felt hardest to claim. If a client shares thoughts of harm, name 988 (call or text) and complete any safety talk in session, not as homework.', '[{"id": "f0", "type": "textarea", "label": "A support I marked and who could give it"}, {"id": "f1", "type": "textarea", "label": "How I could ask for it"}, {"id": "f2", "type": "textarea", "label": "The square that felt hardest to claim"}, {"id": "f3", "type": "textarea", "label": "One ask I will make this week"}, {"id": "f4", "type": "textarea", "label": "988 call or text, and people I can reach"}]'::jsonb, array['perinatal and postpartum', 'support', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('social-situation-story-dice', 'Social Situation Story Dice', 'game'::resource_kind, 'Players roll story dice to build a social scene, then act out a braver ending.', 'Practice small social steps in a playful setting before trying them outside.', array['Teens', 'Groups']::text[], '30 minutes', 'Dice show a place, a person and a small social step, such as asking a question or joining a group. Players build a short scene and play the awkward moment for laughs, then a brave version. Keep stakes low and never force a turn. Debrief on what people noticed about the awkward moment, and pick one real step for the week.', '[{"id": "f0", "type": "textarea", "label": "The scene my dice gave me"}, {"id": "f1", "type": "textarea", "label": "What I feared would happen"}, {"id": "f2", "type": "textarea", "label": "What actually happened in the game"}, {"id": "f3", "type": "textarea", "label": "My real-life step for this week"}]'::jsonb, array['social anxiety', 'exposure', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('memory-lane-story-stones', 'Memory Lane Story Stones', 'game'::resource_kind, 'Players pick painted stones and share a memory of someone they miss, with pacing rules.', 'Give grief a gentle, paced way to be spoken aloud and shared.', array['Adults', 'Groups']::text[], '30 minutes', 'Lay out smooth stones marked with words like laugh, meal, song or place. Each player picks one and shares a memory if they choose, or passes. Others may only say thank you. Set a time limit per turn and keep a grounding pause at the end. Debrief on what felt good to share, and on what needs more room next time.', '[{"id": "f0", "type": "textarea", "label": "The stone I picked and what it brought up"}, {"id": "f1", "type": "textarea", "label": "A memory I chose to share"}, {"id": "f2", "type": "textarea", "label": "What helped me stay steady while sharing"}, {"id": "f3", "type": "textarea", "label": "What I would like more room for"}]'::jsonb, array['grief and loss', 'memory', 'group', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('partner-puzzle-pieces-game', 'Partner Puzzle Pieces Game', 'game'::resource_kind, 'Partners each hold half of a puzzle and earn pieces by sharing their own parts of a conflict.', 'Help couples practice speaking and listening in turns, each partner with a role.', array['Couples']::text[], '30 minutes', 'Each partner holds half of a simple puzzle. Partner A shares a feeling and a need using I statements; Partner B reflects it back, then earns a piece. Swap. The puzzle only completes when both have had both roles. Stop and reset the game if either partner escalates. Debrief on how it felt to listen without defending.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a feeling and a need I shared"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I reflected back"}, {"id": "f2", "type": "textarea", "label": "Partner B: a feeling and a need I shared"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I reflected back"}, {"id": "f4", "type": "textarea", "label": "One thing we will try at home this week"}]'::jsonb, array['relationship issues', 'communication', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('coping-menu-restaurant-role-play', 'Coping Menu Restaurant Role-Play', 'game'::resource_kind, 'Players order from a coping menu as customers while a server suggests sides.', 'Help clients build a personal menu of coping skills they would use.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Write a menu with starters for quick skills, mains for longer ones and desserts for treats that feel good. One player serves, one orders for a stressful moment, and the server suggests a pairing. Swap roles. Debrief on what clients would order first in real life. Encourage clients to take a photo of the menu and keep it handy.', '[{"id": "f0", "type": "textarea", "label": "Starters I would order in a hard moment"}, {"id": "f1", "type": "textarea", "label": "A main I would want when stress is high"}, {"id": "f2", "type": "textarea", "label": "A dessert that feels good to me"}, {"id": "f3", "type": "textarea", "label": "Who I would share my menu with"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-09-30T15:00:00+00:00'::timestamptz),
  ('fear-ladder-floor-game', 'Fear Ladder Floor Game', 'game'::resource_kind, 'Players climb a taped floor ladder of small steps toward a feared thing, with a cheer at each rung.', 'Make gradual steps toward a feared thing playful and paced by the client.', array['Children', 'Teens']::text[], '30 minutes', 'Tape a ladder on the floor with five rungs, each holding a card with a small step the client helps write. The client moves up only when ready, rating the fear at each rung and stopping whenever they choose. A parent cheers, and helps plan practice between sessions. If a child discloses anything worrying, follow your reporting duties. Debrief on the bravest moment.', '[{"id": "f0", "type": "textarea", "label": "The feared thing at the top of my ladder"}, {"id": "f1", "type": "textarea", "label": "My rungs from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "My fear rating at each rung"}, {"id": "f3", "type": "textarea", "label": "The bravest moment today"}, {"id": "f4", "type": "textarea", "label": "How my parent can cheer me on"}]'::jsonb, array['phobias', 'hierarchy', 'exposure', 'play']::text[], '2026-09-30T15:00:00+00:00'::timestamptz)
